"use client";

export {
  SchemaBuilder,
  type ExtendedJSONSchema7,
  type SchemaBuilderFeatures,
  type SchemaBuilderProps,
  type SchemaBuilderView,
} from "@/components/schema-editor/schema-builder";

"use client";

import type {
  DocumentSchemaNodeEditorProps,
  RenderDocumentNodeEditor,
  SchemaEditorMode,
} from "@/components/schema-editor/document-node-editor-types";
import type { SchemaDocument } from "@/components/schema-editor/document/types";
import type { DocumentNodeView } from "@/components/schema-editor/document/view-model";
import type { ResolvedSchemaBuilderFeatures } from "@/components/schema-editor/schema-builder-types";

interface DocumentArrayNodeEditorProps {
  doc: SchemaDocument;
  nodeId: string;
  nodeView: DocumentNodeView;
  path: string;
  setDefsAccordionOpen: (open: boolean) => void;
  draggedParentRef: DocumentSchemaNodeEditorProps["draggedParentRef"];
  draggedPropertyRef: DocumentSchemaNodeEditorProps["draggedPropertyRef"];
  mode: SchemaEditorMode;
  features: ResolvedSchemaBuilderFeatures;
  renderNode: RenderDocumentNodeEditor;
  dispatch: DocumentSchemaNodeEditorProps["dispatch"];
}

export function DocumentArrayNodeEditor({
  dispatch,
  doc,
  nodeId,
  nodeView,
  path,
  setDefsAccordionOpen,
  draggedParentRef,
  draggedPropertyRef,
  mode,
  features,
  renderNode,
}: DocumentArrayNodeEditorProps) {
  const itemView = nodeView.items;
  if (!itemView) {
    return null;
  }

  return (
    <div className="ml-4">
      <div className="border-border ml-4 border-l">
        {renderNode({
          dispatch,
          doc,
          draggedParentRef,
          draggedPropertyRef,
          mode,
          features,
          name: "items",
          nodeId: itemView.nodeId,
          nodeView: itemView,
          path: `${path}.items`,
          canDelete: false,
          hidePencilButton: true,
          setDefsAccordionOpen,
        })}
      </div>
    </div>
  );
}

import * as React from "react";
import { toast } from "sonner";

import type {
  DocumentSchemaNodeEditorProps,
  SchemaEditorMode,
} from "@/components/schema-editor/document-node-editor-types";
import { nodeFromJson } from "@/components/schema-editor/document/convert";
import {
  addDefinition,
  removeDefinition,
  renameDefinition,
} from "@/components/schema-editor/document/definition-operations";
import { isDefinitionReferenced } from "@/components/schema-editor/document/derive";
import { replaceNodeJson } from "@/components/schema-editor/document/json-node";
import { definitionRef } from "@/components/schema-editor/document/json-pointer";
import type {
  DefinitionEntry,
  SchemaDocument,
} from "@/components/schema-editor/document/types";
import { getDocumentNodeView } from "@/components/schema-editor/document/view-model";
import type { SchemaDispatch } from "@/components/schema-editor/schema-builder-types";

interface DocumentDefinitionsEditorControllerOptions {
  dispatch: SchemaDispatch;
  doc: SchemaDocument;
  mode: SchemaEditorMode;
  definitionsEnabled: boolean;
  accordionOpen: boolean;
  setAccordionOpen: (open: boolean) => void;
}

export function useDocumentDefinitionsEditorController({
  dispatch,
  doc,
  mode,
  definitionsEnabled,
  accordionOpen,
  setAccordionOpen,
}: DocumentDefinitionsEditorControllerOptions) {
  const [newDefinitionName, setNewDefinitionName] = React.useState("");
  const editable = mode === "editable";
  const shouldShowClosedPrompt =
    doc.defs.length === 0 && (!accordionOpen || !definitionsEnabled);
  const accordionValue = accordionOpen ? "defs" : "";

  const openDefinitions = React.useCallback(() => {
    setAccordionOpen(true);
  }, [setAccordionOpen]);

  const addNewDefinition = React.useCallback(() => {
    const definitionName = newDefinitionName.trim();
    if (!definitionName) return;

    dispatch(
      (current) =>
        addDefinition(current, {
          name: definitionName,
          node: nodeFromJson(
            { type: "object", properties: {}, required: [] },
            current,
          ),
        }).doc,
    );
    setNewDefinitionName("");
    setAccordionOpen(true);
  }, [dispatch, newDefinitionName, setAccordionOpen]);

  const deleteDefinition = React.useCallback(
    (definition: DefinitionEntry) => {
      if (
        isDefinitionReferenced(doc, definition.id, {
          exceptDefId: definition.id,
        })
      ) {
        toast.error(
          `Cannot delete "${definition.name}" because it is referenced by one or more $ref properties. Remove or update those references first.`,
        );
        return;
      }

      dispatch((current) => removeDefinition(current, definition.id));
      if (doc.defs.length <= 1) {
        setAccordionOpen(false);
      }
    },
    [dispatch, doc, setAccordionOpen],
  );

  const updateDefinition = React.useCallback(
    (
      definition: DefinitionEntry,
      newName: string,
      updatedDefinition?: Parameters<
        NonNullable<DocumentSchemaNodeEditorProps["onNameChange"]>
      >[1],
    ) => {
      if (newName === definition.name && !updatedDefinition) return;

      dispatch((current) => {
        let next = current;
        if (newName !== definition.name) {
          next = renameDefinition(next, definition.id, newName);
        }
        if (updatedDefinition) {
          next = replaceNodeJson(next, definition.node.id, updatedDefinition);
        }
        return next;
      });
    },
    [dispatch],
  );

  const definitionViews = React.useMemo(
    () =>
      doc.defs.map((definition) => ({
        definition,
        nodeView: getDocumentNodeView(doc, definition.node),
        path: definitionRef("$defs", definition.name),
        canDelete: !isDefinitionReferenced(doc, definition.id, {
          exceptDefId: definition.id,
        }),
      })),
    [doc],
  );

  return {
    accordionValue,
    definitionViews,
    editable,
    newDefinitionName,
    setNewDefinitionName,
    shouldShowClosedPrompt,
    openDefinitions,
    addNewDefinition,
    deleteDefinition,
    updateDefinition,
  };
}

"use client";

import * as React from "react";
import { PlusIcon } from "lucide-react";

import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from "@/components/ui/accordion";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { useDocumentDefinitionsEditorController } from "@/components/schema-editor/document-definitions-editor-controller";
import type { SchemaEditorMode } from "@/components/schema-editor/document-node-editor-types";
import {
  definitionElementId,
  DEFINITIONS_SECTION_ID,
} from "@/components/schema-editor/document-node-reveal";
import { DocumentSchemaNodeEditor } from "@/components/schema-editor/document-schema-node-editor";
import type { SchemaDocument } from "@/components/schema-editor/document/types";
import type {
  ResolvedSchemaBuilderFeatures,
  SchemaDispatch,
} from "@/components/schema-editor/schema-builder-types";

interface DocumentDefinitionsEditorProps {
  dispatch: SchemaDispatch;
  doc: SchemaDocument;
  mode: SchemaEditorMode;
  definitionsEnabled: boolean;
  features: ResolvedSchemaBuilderFeatures;
  accordionOpen: boolean;
  setAccordionOpen: (open: boolean) => void;
  draggedParentRef: React.RefObject<string | null>;
  draggedPropertyRef: React.RefObject<string | null>;
}

export function DocumentDefinitionsEditor({
  dispatch,
  doc,
  mode,
  definitionsEnabled,
  features,
  accordionOpen,
  setAccordionOpen,
  draggedParentRef,
  draggedPropertyRef,
}: DocumentDefinitionsEditorProps) {
  const controller = useDocumentDefinitionsEditorController({
    dispatch,
    doc,
    mode,
    definitionsEnabled,
    accordionOpen,
    setAccordionOpen,
  });

  if (controller.shouldShowClosedPrompt) {
    return mode === "descriptionOnly" ? null : (
      <div className="mt-4 flex">
        <div
          className="rounded-md transition-colors duration-300"
          id={DEFINITIONS_SECTION_ID}
        >
          {definitionsEnabled ? (
            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={controller.openDefinitions}
            >
              <PlusIcon className="h-4 w-4" />
              <span>Add definition</span>
            </Button>
          ) : null}
        </div>
      </div>
    );
  }

  return (
    <Accordion
      type="single"
      collapsible
      id={DEFINITIONS_SECTION_ID}
      className="border-border mt-6 w-full rounded-lg border px-4 pb-0"
      value={controller.accordionValue}
      onValueChange={(value) => setAccordionOpen(value === "defs")}
    >
      <AccordionItem value="defs" className="border-none bg-transparent">
        <AccordionTrigger className="text-muted-foreground bg-transparent font-medium">
          <div className="flex items-center">
            Definitions ({doc.defs.length})
          </div>
        </AccordionTrigger>
        <AccordionContent className="bg-transparent px-1 pt-2">
          <div className="space-y-4">
            {doc.defs.length === 0 && (
              <p className="text-muted-foreground text-sm">
                Create reusable schema components to avoid duplication with a
                new definition.
              </p>
            )}
            {controller.definitionViews.map((definitionView) => {
              const { definition } = definitionView;
              return (
                <div
                  key={definition.id}
                  className="py-2 transition-colors duration-300"
                  id={definitionElementId(definition.id)}
                >
                  <DocumentSchemaNodeEditor
                    dispatch={dispatch}
                    doc={doc}
                    draggedParentRef={draggedParentRef}
                    draggedPropertyRef={draggedPropertyRef}
                    mode={definitionsEnabled ? mode : "readOnly"}
                    features={features}
                    name={definition.name}
                    nodeId={definition.node.id}
                    nodeView={definitionView.nodeView}
                    onNameChange={(newName, updatedDefinition) =>
                      controller.updateDefinition(
                        definition,
                        newName,
                        updatedDefinition,
                      )
                    }
                    path={definitionView.path}
                    canDelete={definitionView.canDelete}
                    onDelete={() => controller.deleteDefinition(definition)}
                    setDefsAccordionOpen={setAccordionOpen}
                  />
                </div>
              );
            })}
            {controller.editable && definitionsEnabled && (
              <div className="flex items-center gap-3">
                <Input
                  placeholder="New definition name"
                  className="w-40"
                  value={controller.newDefinitionName}
                  onChange={(event) =>
                    controller.setNewDefinitionName(event.target.value)
                  }
                />
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  disabled={!controller.newDefinitionName.trim()}
                  onClick={controller.addNewDefinition}
                >
                  <PlusIcon className="h-4 w-4" />
                  <span>Add</span>
                </Button>
              </div>
            )}
          </div>
        </AccordionContent>
      </AccordionItem>
    </Accordion>
  );
}

"use client";

import { useState } from "react";

import type {
  DocumentSchemaNodeEditorProps,
  SchemaEditorMode,
} from "@/components/schema-editor/document-node-editor-types";
import {
  addEnumValue,
  removeEnumValue,
  updateEnumValue,
} from "@/components/schema-editor/document/enum-operations";
import type { EnumValue } from "@/components/schema-editor/document/types";
import { SchemaChipAddRow } from "@/components/schema-editor/primitives/schema-chip-add-row";
import { SchemaChipList } from "@/components/schema-editor/primitives/schema-chip-list";

interface DocumentEnumNodeEditorProps {
  dispatch: DocumentSchemaNodeEditorProps["dispatch"];
  mode: SchemaEditorMode;
  nodeId: string;
  enumEntries: EnumValue[];
}

export function DocumentEnumNodeEditor({
  dispatch,
  mode,
  nodeId,
  enumEntries,
}: DocumentEnumNodeEditorProps) {
  const [newEnumValue, setNewEnumValue] = useState("");
  const editable = mode === "editable";
  const canAddEnumValue = newEnumValue.trim().length > 0;

  const handleAddEnum = () => {
    if (!canAddEnumValue) return;
    dispatch((current) => addEnumValue(current, nodeId, newEnumValue.trim()));
    setNewEnumValue("");
  };

  const handleRemoveEnum = (id: string) => {
    dispatch((current) => removeEnumValue(current, nodeId, id));
  };

  const handleEditEnum = (id: string, newValue: string) => {
    dispatch((current) =>
      updateEnumValue(current, nodeId, id, { value: newValue }),
    );
  };
  const addInput = {
    focusAfterSubmit: true,
    inputLabel: "New choice",
    placeholder: "New choice",
    submitLabel: "Add",
    value: newEnumValue,
    onChange: setNewEnumValue,
    onSubmit: handleAddEnum,
  };

  return (
    <div className="ml-6">
      <div className="mt-1 mb-2">
        <SchemaChipList
          editable={editable}
          items={enumEntries.map((entry, index) => {
            const value = String(entry.value);
            return {
              id: entry.id,
              inputLabel: `Option ${index + 1}: ${value || "empty"}`,
              removeLabel: `Remove option ${value}`,
              value,
            };
          })}
          onRemove={handleRemoveEnum}
          onReplace={handleEditEnum}
        />
        {editable && (
          <SchemaChipAddRow addInput={addInput} editable={editable} />
        )}
      </div>

      {enumEntries.length === 0 && !editable && (
        <div className="text-muted-foreground mb-2 text-sm">
          No enum values defined.
        </div>
      )}
    </div>
  );
}

"use client";

import { SchemaRowActions } from "@/components/schema-editor/primitives/schema-row-actions";

interface DocumentNodeActionsProps {
  canDelete: boolean;
  mode: "descriptionOnly" | "readOnly" | "editable";
  editable: boolean;
  hidePencilButton: boolean;
  onDelete?: () => void;
  onOpenMetadata: () => void;
}

export function DocumentNodeActions(props: DocumentNodeActionsProps) {
  const details =
    props.hidePencilButton || !props.onOpenMetadata
      ? undefined
      : props.mode === "readOnly"
        ? {
            label: "View field properties",
            mode: "view" as const,
            onOpen: props.onOpenMetadata,
          }
        : {
            label: "Edit field properties",
            mode: "edit" as const,
            onOpen: props.onOpenMetadata,
          };

  return (
    <SchemaRowActions
      canDelete={props.canDelete}
      editable={props.editable}
      details={details}
      onDelete={props.onDelete}
    />
  );
}

"use client";

import { SchemaInlineDescription } from "@/components/schema-editor/primitives/schema-inline-description";

interface DocumentNodeDescriptionControlProps {
  description: string;
  mode: "descriptionOnly" | "readOnly" | "editable";
  onOpenMetadata: () => void;
  onSubmitDescription: (description: string) => void;
}

export function DocumentNodeDescriptionControl({
  description,
  mode,
  onOpenMetadata,
  onSubmitDescription,
}: DocumentNodeDescriptionControlProps) {
  return (
    <SchemaInlineDescription
      ariaLabel="Field description"
      value={description}
      editable={mode !== "readOnly"}
      onOpenDetails={onOpenMetadata}
      onCommit={onSubmitDescription}
    />
  );
}

import type * as React from "react";

import type { SchemaDocument } from "@/components/schema-editor/document/types";
import type { DocumentNodeView } from "@/components/schema-editor/document/view-model";
import type { ExtendedJSONSchema7 } from "@/components/schema-editor/lib/json-schema-types";
import type {
  ResolvedSchemaBuilderFeatures,
  SchemaDispatch,
} from "@/components/schema-editor/schema-builder-types";
import type { SchemaEditorMode } from "@/components/schema-editor/schema-editor-mode";

export type { SchemaEditorMode };

export interface DocumentSchemaNodeEditorProps {
  dispatch: SchemaDispatch;
  doc: SchemaDocument;
  name: string;
  nodeId: string;
  nodeView: DocumentNodeView;
  path: string;
  canDelete?: boolean;
  onDelete?: () => void;
  onNameChange?: (newName: string, updatedNode?: ExtendedJSONSchema7) => void;
  setDefsAccordionOpen: (open: boolean) => void;
  draggedParentRef: React.RefObject<string | null>;
  draggedPropertyRef: React.RefObject<string | null>;
  mode?: SchemaEditorMode;
  hidePencilButton?: boolean;
  isRequired?: boolean;
  onRequiredChange?: (required: boolean) => void;
  siblingNames?: string[];
  features?: ResolvedSchemaBuilderFeatures;
}

export type RenderDocumentNodeEditor = (
  props: DocumentSchemaNodeEditorProps,
) => React.ReactNode;

import * as React from "react";
import type { JSONSchema7Definition } from "json-schema";

import {
  revealDefinitionElement,
  revealDefinitionsSection,
} from "@/components/schema-editor/document-node-reveal";
import { projectNode } from "@/components/schema-editor/document/convert";
import { setRefByName } from "@/components/schema-editor/document/definition-operations";
import { setEnumValues } from "@/components/schema-editor/document/enum-operations";
import { setNodeDescription } from "@/components/schema-editor/document/node-metadata";
import {
  setNodeEditorType,
  type SchemaEditorType,
} from "@/components/schema-editor/document/type-operations";
import type { SchemaDocument } from "@/components/schema-editor/document/types";
import type { DocumentNodeView } from "@/components/schema-editor/document/view-model";
import type { ExtendedJSONSchema7 } from "@/components/schema-editor/lib/json-schema-types";
import type { PropertyFormCommand } from "@/components/schema-editor/property-form/types";
import type { SchemaDispatch } from "@/components/schema-editor/schema-builder-types";

interface DocumentNodeHeaderControllerOptions {
  dispatch: SchemaDispatch;
  doc: SchemaDocument;
  nodeId: string;
  nodeView: DocumentNodeView;
  setDefsAccordionOpen: (open: boolean) => void;
}

export function useDocumentNodeHeaderController({
  dispatch,
  doc,
  nodeId,
  nodeView,
  setDefsAccordionOpen,
}: DocumentNodeHeaderControllerOptions) {
  const schemaNode = projectNode(doc, nodeView.docNode) as ExtendedJSONSchema7;
  const defs = React.useMemo(() => {
    const next: Record<string, JSONSchema7Definition> = {};
    for (const definition of doc.defs) {
      setRecordValue(next, definition.name, projectNode(doc, definition.node));
    }
    return next;
  }, [doc]);
  const localType = nodeView.type;
  const description = nodeView.description || "";
  const refName = localType === "$ref" ? nodeView.refName : undefined;

  const [metadataDialogOpen, setMetadataDialogOpen] = React.useState(false);
  const [enumCreationDialogOpen, setEnumCreationDialogOpen] =
    React.useState(false);

  const showDefinition = React.useCallback(
    (definitionName: string) => {
      setDefsAccordionOpen(true);
      const definition = doc.defs.find((def) => def.name === definitionName);
      if (definition) {
        revealDefinitionElement(definition.id);
      }
    },
    [doc.defs, setDefsAccordionOpen],
  );

  const showDefinitionsSection = React.useCallback(() => {
    setDefsAccordionOpen(true);
    revealDefinitionsSection();
  }, [setDefsAccordionOpen]);

  const selectType = React.useCallback(
    (newType: SchemaEditorType | "enum") => {
      if (newType === "enum") {
        if (localType !== "enum") {
          setEnumCreationDialogOpen(true);
        }
        return;
      }
      dispatch((current) =>
        setNodeEditorType(current, nodeId, newType as SchemaEditorType),
      );
    },
    [dispatch, localType, nodeId],
  );

  const confirmEnumValues = React.useCallback(
    (enumValues: string[]) => {
      dispatch((current) => setEnumValues(current, nodeId, enumValues));
    },
    [dispatch, nodeId],
  );

  const submitDescription = React.useCallback(
    (nextDescription: string) => {
      dispatch((current) =>
        setNodeDescription(current, nodeId, nextDescription || undefined),
      );
    },
    [dispatch, nodeId],
  );

  const selectDefinition = React.useCallback(
    (definitionName: string) => {
      dispatch((current) => setRefByName(current, nodeId, definitionName));
    },
    [dispatch, nodeId],
  );

  const selectObjectTemplate = React.useCallback(
    (templateName: string) => {
      void import("./optional/object-templates/object-template-reference").then(
        ({ applyObjectTemplateReferenceToDocument }) => {
          dispatch((current) =>
            applyObjectTemplateReferenceToDocument(
              current,
              nodeId,
              templateName,
            ),
          );
        },
      );
    },
    [dispatch, nodeId],
  );

  const handlePropertyFormCommand = React.useCallback(
    async (command: PropertyFormCommand) => {
      if (command.type === "createDefinition") {
        showDefinitionsSection();
        return;
      }

      if (command.type === "installObjectTemplate") {
        const { addObjectTemplateDefinitionsToDocument } = await import(
          "./optional/object-templates/object-template-reference"
        );
        dispatch((current) =>
          addObjectTemplateDefinitionsToDocument(current, command.templateName),
        );
      }
    },
    [dispatch, showDefinitionsSection],
  );

  return {
    schemaNode,
    defs,
    localType,
    description,
    refName,
    metadataDialogOpen,
    setMetadataDialogOpen,
    enumCreationDialogOpen,
    setEnumCreationDialogOpen,
    showDefinition,
    showDefinitionsSection,
    selectType,
    confirmEnumValues,
    submitDescription,
    selectDefinition,
    selectObjectTemplate,
    handlePropertyFormCommand,
  };
}

function setRecordValue<T>(record: Record<string, T>, key: string, value: T) {
  Object.defineProperty(record, key, {
    value,
    enumerable: true,
    configurable: true,
    writable: true,
  });
}

"use client";

import * as React from "react";

import { DocumentNodeActions } from "@/components/schema-editor/document-node-actions";
import { DocumentNodeDescriptionControl } from "@/components/schema-editor/document-node-description-control";
import type {
  DocumentSchemaNodeEditorProps,
  SchemaEditorMode,
} from "@/components/schema-editor/document-node-editor-types";
import { useDocumentNodeHeaderController } from "@/components/schema-editor/document-node-header-controller";
import { DocumentNodeNameControl } from "@/components/schema-editor/document-node-name-control";
import { DocumentNodeTypeMenu } from "@/components/schema-editor/document-node-type-menu";
import type { SchemaDocument } from "@/components/schema-editor/document/types";
import type { DocumentNodeView } from "@/components/schema-editor/document/view-model";
import type { ExtendedJSONSchema7 } from "@/components/schema-editor/lib/json-schema-types";
import { NodeDialog } from "@/components/schema-editor/node-dialog";
import { SchemaFieldRow } from "@/components/schema-editor/primitives/schema-field-row";

import { EnumCreationDialog } from "./enum-creation-dialog";

interface DocumentNodeHeaderProps
  extends Omit<
    DocumentSchemaNodeEditorProps,
    "draggedParentRef" | "draggedPropertyRef"
  > {
  doc: SchemaDocument;
  nodeView: DocumentNodeView;
  mode: SchemaEditorMode;
  features: NonNullable<DocumentSchemaNodeEditorProps["features"]>;
  onChange: (newNode: ExtendedJSONSchema7) => void;
}

export function DocumentNodeHeader({
  dispatch,
  doc,
  name,
  nodeView,
  nodeId,
  path,
  canDelete = false,
  onDelete,
  onNameChange,
  setDefsAccordionOpen,
  mode,
  hidePencilButton = false,
  siblingNames = [],
  features,
  onChange,
}: DocumentNodeHeaderProps) {
  const editable = mode === "editable";
  const controller = useDocumentNodeHeaderController({
    dispatch,
    doc,
    nodeId,
    nodeView,
    setDefsAccordionOpen,
  });

  return (
    <>
      {path !== "#" && (
        <SchemaFieldRow
          id={`schema-field-${path.replace(/^#\.?/, "").split(".").join("-")}`}
          grip={editable ? "drag" : "empty"}
          name={
            <DocumentNodeNameControl
              editable={editable}
              name={name}
              siblingNames={siblingNames}
              canRename={Boolean(onNameChange)}
              isReference={controller.localType === "$ref"}
              refName={controller.refName}
              onNameChange={onNameChange}
              onShowDefinition={controller.showDefinition}
            />
          }
          description={
            <DocumentNodeDescriptionControl
              description={controller.description}
              mode={mode}
              onOpenMetadata={() => controller.setMetadataDialogOpen(true)}
              onSubmitDescription={controller.submitDescription}
            />
          }
          actions={
            <DocumentNodeActions
              canDelete={canDelete}
              editable={editable}
              mode={mode}
              hidePencilButton={hidePencilButton}
              onDelete={onDelete}
              onOpenMetadata={() => controller.setMetadataDialogOpen(true)}
            />
          }
          type={
            <DocumentNodeTypeMenu
              defs={controller.defs}
              editable={editable}
              features={features}
              localType={controller.localType}
              refName={controller.refName}
              onCreateDefinition={controller.showDefinitionsSection}
              onSelectDefinition={controller.selectDefinition}
              onSelectObjectTemplate={controller.selectObjectTemplate}
              onSelectType={controller.selectType}
            />
          }
        />
      )}

      {path !== "#" && controller.metadataDialogOpen ? (
        <NodeDialog
          isOpen={controller.metadataDialogOpen}
          onClose={() => controller.setMetadataDialogOpen(false)}
          onChange={onChange}
          onNameChange={onNameChange || (() => {})}
          onDelete={
            editable && canDelete
              ? () => {
                  if (onDelete) {
                    onDelete();
                    controller.setMetadataDialogOpen(false);
                  }
                }
              : undefined
          }
          node={controller.schemaNode}
          name={name}
          mode={mode}
          siblingNames={siblingNames}
          formContext={{
            schemaDefinitions: controller.defs || {},
            fieldPath: path,
            objectTemplatesEnabled: features.objectTemplates,
            onCommand: controller.handlePropertyFormCommand,
          }}
        />
      ) : null}

      <EnumCreationDialog
        isOpen={controller.enumCreationDialogOpen}
        onClose={() => controller.setEnumCreationDialogOpen(false)}
        onConfirm={controller.confirmEnumValues}
        onCancel={() => undefined}
      />
    </>
  );
}

"use client";

