function changeNodeJson(
  doc: SchemaDocument,
  nodeId: string,
  nextNode: ExtendedJSONSchema7,
) {
  return replaceNodeJson(doc, nodeId, nextNode);
}

export function DocumentSchemaNodeEditor({
  dispatch,
  doc,
  name,
  nodeId,
  nodeView,
  path,
  canDelete = false,
  onDelete,
  onNameChange,
  setDefsAccordionOpen,
  draggedParentRef,
  draggedPropertyRef,
  mode = "editable",
  hidePencilButton = false,
  isRequired,
  onRequiredChange,
  siblingNames = [],
  features: featuresProp,
}: DocumentSchemaNodeEditorProps) {
  const features =
    featuresProp ??
    resolveSchemaBuilderFeatures({
      definitions: true,
      objectTemplates: true,
      jsonMode: true,
      importExport: true,
    });
  const onChange = React.useCallback(
    (newNode: ExtendedJSONSchema7) => {
      dispatch((current) => changeNodeJson(current, nodeId, newNode));
    },
    [dispatch, nodeId],
  );

  const renderNode = React.useCallback<RenderDocumentNodeEditor>(
    (props) => <DocumentSchemaNodeEditor {...props} />,
    [],
  );

  const localType = nodeView.type;

  return (
    <div>
      <DocumentNodeHeader
        dispatch={dispatch}
        doc={doc}
        name={name}
        nodeView={nodeView}
        nodeId={nodeId}
        path={path}
        canDelete={canDelete}
        onDelete={onDelete}
        onNameChange={onNameChange}
        setDefsAccordionOpen={setDefsAccordionOpen}
        mode={mode}
        hidePencilButton={hidePencilButton}
        isRequired={isRequired}
        onRequiredChange={onRequiredChange}
        siblingNames={siblingNames}
        features={features}
        onChange={onChange}
      />

      {localType === "object" && (
        <DocumentObjectNodeEditor
          dispatch={dispatch}
          doc={doc}
          nodeId={nodeId}
          nodeView={nodeView}
          path={path}
          setDefsAccordionOpen={setDefsAccordionOpen}
          draggedParentRef={draggedParentRef}
          draggedPropertyRef={draggedPropertyRef}
          mode={mode}
          features={features}
          renderNode={renderNode}
        />
      )}

      {localType === "array" && (
        <DocumentArrayNodeEditor
          dispatch={dispatch}
          doc={doc}
          nodeId={nodeId}
          nodeView={nodeView}
          path={path}
          setDefsAccordionOpen={setDefsAccordionOpen}
          draggedParentRef={draggedParentRef}
          draggedPropertyRef={draggedPropertyRef}
          mode={mode}
          features={features}
          renderNode={renderNode}
        />
      )}

      {localType === "enum" && (
        <DocumentEnumNodeEditor
          dispatch={dispatch}
          mode={mode}
          nodeId={nodeId}
          enumEntries={nodeView.enumEntries}
        />
      )}
    </div>
  );
}

export function mapPreserve<T>(
  items: T[],
  fn: (item: T, index: number) => T,
): T[] {
  let changed = false;
  const next = items.map((item, index) => {
    const result = fn(item, index);
    if (result !== item) changed = true;
    return result;
  });
  return changed ? next : items;
}

import type { JSONSchema7, JSONSchema7Definition } from "json-schema";

import { createId } from "./id";
import {
  definitionRefAliases,
  definitionRef,
  type DefinitionsKeyword,
} from "./json-pointer";
import type {
  DefinitionEntry,
  DocumentNode,
  EnumValue,
  JsonValue,
  PropertyEntry,
  SchemaDocument,
} from "./types";

/**
 * Boundary conversions between vanilla JSON Schema (the wire format) and the
 * editor Document (the in-memory source of truth).
 *
 *  - `fromJsonSchema` is TOTAL: it mints fresh ids, distributes `required`, and
 *    carries every unmodeled keyword into `rest`. Run it ONCE when a new external
 *    schema arrives — not on every render.
 *  - `toJsonSchema` is a PURE PROJECTION: it rebuilds `required[]`, re-projects
 *    `$ref` from the target definition's current name, and drops transient-invalid
 *    artifacts (empty/duplicate property keys). Run it on demand for
 *    `onSchemaChange` and the JSON preview.
 *
 * Together they round-trip losslessly for everything the editor surfaces, and
 * carry everything it doesn't.
 */

/** Keys consumed structurally by a node; everything else falls into `rest`. */
const MODELED_NODE_KEYS = new Set<string>([
  "type",
  "title",
  "description",
  "properties",
  "required",
  "items",
  "enum",
  "$ref",
  "anyOf",
  "oneOf",
  "allOf",
]);

type RefMap = Map<string, string>; // json-pointer string -> definition NodeId
type CreateDocumentId = (prefix?: string) => string;

// ---------------------------------------------------------------------------
// Import: JSON Schema -> Document
// ---------------------------------------------------------------------------

export function fromJsonSchema(schema: JSONSchema7): SchemaDocument {
  const createImportId = createDeterministicImportIdFactory();
  const hasDefsKeyword = schema.$defs !== undefined;
  const hasDefinitionsKeyword = schema.definitions !== undefined;
  const defsKeyword = schema.$defs
    ? "$defs"
    : schema.definitions
      ? "definitions"
      : "$defs";
  const rawDefs = (schema.$defs ?? schema.definitions ?? {}) as Record<
    string,
    JSONSchema7Definition
  >;

  // First pass: give every top-level definition an id so refs can resolve to it.
  const defEntries: DefinitionEntry[] = Object.keys(rawDefs).map((name) => ({
    id: createImportId("def"),
    name,
    node: { id: createImportId(), rest: {} }, // placeholder, filled in second pass
  }));
  const refMap: RefMap = new Map();
  for (const def of defEntries) {
    addDefinitionRefMapEntries(refMap, def, {
      defsKeyword,
      hasOtherDefsKeyword:
        defsKeyword === "$defs" ? hasDefinitionsKeyword : hasDefsKeyword,
    });
  }

  // Second pass: build each definition's node now that the ref map exists.
  for (const def of defEntries) {
    def.node = nodeFromSchema(rawDefs[def.name], refMap, {
      createDocumentId: createImportId,
    });
  }

  // Strip only the PRIMARY defs keyword from the root; if the (unusual) other
  // keyword is also present, it's carried verbatim in `rest` so it isn't lost.
  const root = nodeFromSchema(schema, refMap, {
    stripKeyword: defsKeyword,
    createDocumentId: createImportId,
  });

  return {
    root,
    defs: defEntries,
    rest: { defsKeyword },
  };
}

function nodeFromSchema(
  schema: JSONSchema7Definition,
  refMap: RefMap,
  options: {
    createDocumentId?: CreateDocumentId;
    stripKeyword?: string;
  } = {},
): DocumentNode {
  const createDocumentId = options.createDocumentId ?? createId;

  // A boolean schema (`true` / `false`) has no structure to model — preserve it.
  if (typeof schema === "boolean") {
    return { id: createDocumentId(), rest: {}, booleanSchema: schema };
  }

  const node: DocumentNode = { id: createDocumentId(), rest: {} };

  // Record the source key order so the projection can replay it exactly,
  // keeping round-trips byte-faithful (no $defs/keyword reshuffling on edit).
  node.order = Object.keys(schema);

  if (typeof schema.$ref === "string") {
    const defId = refMap.get(schema.$ref);
    if (defId) node.ref = defId;
    else {
      // unresolved pointer — keep verbatim
      setRecordValue(node.rest, "$ref", schema.$ref);
    }
  }

  if (schema.type !== undefined) node.type = schema.type;
  if (schema.title !== undefined) node.title = schema.title;
  if (schema.description !== undefined) node.description = schema.description;

  if (Array.isArray(schema.enum)) {
    node.enum = enumFromSchema(schema, createDocumentId);
  }

  const required = Array.isArray(schema.required) ? schema.required : [];
  if (required.length > 0 || node.order?.includes("required")) {
    node.requiredOrder = required;
  }

  if (schema.properties) {
    node.properties = Object.entries(schema.properties).map(
      ([key, child]): PropertyEntry => ({
        id: createDocumentId("prop"),
        key,
        required: required.includes(key),
        node: nodeFromSchema(child, refMap, { createDocumentId }),
      }),
    );
  }

  if (required.length > 0) {
    const propertyKeys = new Set(
      node.properties?.map((property) => property.key),
    );
    const extraRequired = required.filter((key) => !propertyKeys.has(key));
    if (extraRequired.length > 0) node.extraRequired = extraRequired;
  }

  if (schema.items !== undefined) {
    if (Array.isArray(schema.items)) {
      // Tuple `items` (array form) is rare and not UI-editable; carry it
      // verbatim in `rest` so it survives the round-trip losslessly.
      setRecordValue(node.rest, "items", schema.items);
    } else {
      node.items = nodeFromSchema(schema.items, refMap, { createDocumentId });
    }
  }

  for (const key of ["anyOf", "oneOf", "allOf"] as const) {
    const value = schema[key];
    if (Array.isArray(value)) {
      node[key] = value.map((sub) =>
        nodeFromSchema(sub, refMap, { createDocumentId }),
      );
    }
  }

  // Carry every keyword we don't model.
  for (const [key, value] of Object.entries(schema)) {
    if (MODELED_NODE_KEYS.has(key)) continue;
    if (options.stripKeyword && key === options.stripKeyword) continue;
    setRecordValue(node.rest, key, value);
  }

  return node;
}

function enumFromSchema(
  schema: JSONSchema7,
  createDocumentId: CreateDocumentId = createId,
): EnumValue[] {
  return (schema.enum ?? []).map(
    (value): EnumValue => ({
      id: createDocumentId("enum"),
      value: value as JsonValue,
    }),
  );
}

function createDeterministicImportIdFactory(): CreateDocumentId {
  let nextId = 0;
  return (prefix = "node") => {
    nextId += 1;
    return `${prefix}-import-${nextId}`;
  };
}

// ---------------------------------------------------------------------------
// Export: Document -> JSON Schema
// ---------------------------------------------------------------------------

export function toJsonSchema(doc: SchemaDocument): JSONSchema7 {
  const defsKeyword =
    doc.rest.defsKeyword === "definitions" ? "definitions" : "$defs";
  const defNameById = new Map<string, string>();
  for (const def of doc.defs) defNameById.set(def.id, def.name);

  const out = nodeToSchema(doc.root, defNameById, defsKeyword) as JSONSchema7;

  if (doc.defs.length > 0) {
    const bag: Record<string, JSONSchema7Definition> = {};
    for (const def of doc.defs) {
      setRecordValue(
        bag,
        def.name,
        nodeToSchema(def.node, defNameById, defsKeyword),
      );
    }
    setRecordValue(out as Record<string, unknown>, defsKeyword, bag);
  }

  // Replay the root key order (so $defs lands back where the source had it).
  return applyKeyOrder(
    out as Record<string, unknown>,
    doc.root.order,
  ) as JSONSchema7;
}

/**
 * Project a single node to JSON Schema (using the document's definition names for
 * any `$ref`s). The inverse of `nodeFromJson` — together they let a component read
 * and rewrite one node's JSON by id while the Document stays the source of truth.
 */
export function projectNode(
  doc: SchemaDocument,
  node: DocumentNode,
): JSONSchema7Definition {
  const defsKeyword =
    doc.rest.defsKeyword === "definitions" ? "definitions" : "$defs";
  const defNameById = new Map<string, string>();
  for (const def of doc.defs) defNameById.set(def.id, def.name);
  return nodeToSchema(node, defNameById, defsKeyword);
}

/** Convert a JSON Schema subtree into a Document node, resolving `$ref`s against
 *  the document's existing definitions (so refs survive the round-trip). */
export function nodeFromJson(
  schema: JSONSchema7Definition,
  doc: SchemaDocument,
): DocumentNode {
  const refMap: RefMap = new Map();
  const defsKeyword =
    doc.rest.defsKeyword === "definitions" ? "definitions" : "$defs";
  const otherDefsKeyword = defsKeyword === "$defs" ? "definitions" : "$defs";
  const hasOtherDefsKeyword = Object.prototype.hasOwnProperty.call(
    doc.root.rest,
    otherDefsKeyword,
  );
  for (const def of doc.defs) {
    addDefinitionRefMapEntries(refMap, def, {
      defsKeyword,
      hasOtherDefsKeyword,
    });
  }
  // Strip the document's primary defs keyword — definitions live at the document
  // level, not on a node; this keeps a root-level edit (whose JSON still carries
  // `$defs`) from duplicating them into the root node's `rest`.
  return nodeFromSchema(schema, refMap, { stripKeyword: defsKeyword });
}

function addDefinitionRefMapEntries(
  refMap: RefMap,
  def: DefinitionEntry,
  options: {
    defsKeyword: "$defs" | "definitions";
    hasOtherDefsKeyword: boolean;
  },
) {
  for (const ref of definitionRefAliases(options.defsKeyword, def.name)) {
    refMap.set(ref, def.id);
  }
  if (!options.hasOtherDefsKeyword) {
    const otherKeyword =
      options.defsKeyword === "$defs" ? "definitions" : "$defs";
    for (const ref of definitionRefAliases(otherKeyword, def.name)) {
      refMap.set(ref, def.id);
    }
  }
}

function nodeToSchema(
  node: DocumentNode,
  defNameById: Map<string, string>,
  defsKeyword: DefinitionsKeyword,
): JSONSchema7Definition {
  if (node.booleanSchema !== undefined) {
    return node.booleanSchema;
  }

  // Emit modeled keys first in a natural reading order ($ref, type, title, …),
  // then any unmodeled keywords. Export is a projection, so it normalizes key
  // order the way a formatter would — semantics are preserved, not byte layout.
  const out: Record<string, unknown> = {};

  if (node.ref) {
    const name = defNameById.get(node.ref);
    if (name) setRecordValue(out, "$ref", definitionRef(defsKeyword, name));
  }

  if (node.type !== undefined) setRecordValue(out, "type", node.type);
  if (node.title !== undefined) setRecordValue(out, "title", node.title);
  if (node.description !== undefined)
    setRecordValue(out, "description", node.description);

  if (node.enum) {
    setRecordValue(
      out,
      "enum",
      node.enum.map((entry) => entry.value),
    );
  }

  if (node.properties) {
    const properties: Record<string, JSONSchema7Definition> = {};
    const required: string[] = [];
    const seen = new Set<string>();
    for (const entry of node.properties) {
      const key = entry.key;
      // Transient-invalid states live in the Document, not the projection:
      // drop empty and duplicate keys at the boundary.
      if ((entry.isTransient && !key) || seen.has(key)) continue;
      seen.add(key);
      setRecordValue(
        properties,
        key,
        nodeToSchema(entry.node, defNameById, defsKeyword),
      );
      if (entry.required) required.push(key);
    }
    setRecordValue(out, "properties", properties);
    // Emit `required` when it has entries, or when the source had an explicit
    // (possibly empty) `required` key — so `required: []` round-trips faithfully.
    const hadRequiredKey = node.order?.includes("required") ?? false;
    const projectedRequired = orderRequiredNames(
      [...(node.extraRequired ?? []), ...required],
      node.requiredOrder,
    );
    if (projectedRequired.length > 0 || hadRequiredKey) {
      setRecordValue(out, "required", projectedRequired);
    }
  } else if (node.extraRequired?.length) {
    setRecordValue(
      out,
      "required",
      orderRequiredNames(node.extraRequired, node.requiredOrder),
    );
  }

  if (node.items) {
    setRecordValue(
      out,
      "items",
      nodeToSchema(node.items, defNameById, defsKeyword),
    );
  }

  for (const key of ["anyOf", "oneOf", "allOf"] as const) {
    const value = node[key];
    if (value) {
      setRecordValue(
        out,
        key,
        value.map((sub) => nodeToSchema(sub, defNameById, defsKeyword)),
      );
    }
  }

  // Trailing unmodeled keywords (const, default, format, pattern, x-*, …).
  for (const [key, value] of Object.entries(node.rest)) {
    if (hasOwn(out, key)) continue; // modeled field already won this key
    setRecordValue(out, key, value);
  }

  return applyKeyOrder(out, node.order) as JSONSchema7;
}

/**
 * Reorder an object's keys to match a recorded source order. Keys present in
 * `order` come first (in that order); any keys not in it (newly added by edits)
 * are appended in their current order. Returns a new object.
 */
function applyKeyOrder(
  obj: Record<string, unknown>,
  order: unknown,
): Record<string, unknown> {
  if (!Array.isArray(order)) return obj;
  const result: Record<string, unknown> = {};
  for (const key of order as string[]) {
    if (hasOwn(obj, key)) setRecordValue(result, key, obj[key]);
  }
  for (const key of Object.keys(obj)) {
    if (!hasOwn(result, key)) setRecordValue(result, key, obj[key]);
  }
  return result;
}

function hasOwn(record: Record<string, unknown>, key: string): boolean {
  return Object.prototype.hasOwnProperty.call(record, key);
}

function setRecordValue<T>(record: Record<string, T>, key: string, value: T) {
  Object.defineProperty(record, key, {
    value,
    enumerable: true,
    configurable: true,
    writable: true,
  });
}

function orderRequiredNames(names: string[], sourceOrder: unknown): string[] {
  const uniqueNames = [...new Set(names)];
  if (!Array.isArray(sourceOrder)) return uniqueNames;

  const remaining = new Set(uniqueNames);
  const ordered: string[] = [];
  for (const name of sourceOrder) {
    if (typeof name !== "string" || !remaining.has(name)) continue;
    ordered.push(name);
    remaining.delete(name);
  }
  ordered.push(...remaining);
  return ordered;
}

import { mapPreserve } from "@/components/schema-editor/document/array";
import { createId } from "@/components/schema-editor/document/id";
import {
  definitionRef,
  definitionRefAliases,
} from "@/components/schema-editor/document/json-pointer";
import { updateNode } from "@/components/schema-editor/document/node-update";
import {
  createNode,
  stripSchemaTypeSpecificRest,
  updateEffectiveNodeShape,
} from "@/components/schema-editor/document/type-operations";
import type {
  DefinitionEntry,
  DocumentNode,
  SchemaDocument,
} from "@/components/schema-editor/document/types";

const SCHEMA_VALUE_REST_KEYS = new Set([
  "additionalItems",
  "additionalProperties",
  "allOf",
  "anyOf",
  "contains",
  "else",
  "if",
  "items",
  "not",
  "oneOf",
  "prefixItems",
  "propertyNames",
  "then",
  "unevaluatedItems",
  "unevaluatedProperties",
]);

const SCHEMA_MAP_REST_KEYS = new Set([
  "$defs",
  "definitions",
  "dependentSchemas",
  "dependencies",
  "patternProperties",
  "properties",
]);

export function addDefinition(
  doc: SchemaDocument,
  init: Partial<DefinitionEntry> = {},
): { doc: SchemaDocument; defId: string } {
  const baseName = init.name?.trim() || "Definition";
  const entry: DefinitionEntry = {
    id: init.id ?? createId("def"),
    name: uniqueDefinitionName(doc, baseName),
    node: init.node ?? createNode("object"),
  };
  return { doc: { ...doc, defs: [...doc.defs, entry] }, defId: entry.id };
}

export function renameDefinition(
  doc: SchemaDocument,
  defId: string,
  name: string,
): SchemaDocument {
  const currentDefinition = doc.defs.find(
    (definition) => definition.id === defId,
  );
  if (!currentDefinition) return doc;

  const nextName = name.trim();
  if (!nextName) return doc;

  const taken = new Set(
    doc.defs
      .filter((definition) => definition.id !== defId)
      .map((definition) => definition.name),
  );
  let finalName = nextName;
  if (taken.has(finalName)) {
    let index = 2;
    while (taken.has(`${nextName}${index}`)) index += 1;
    finalName = `${nextName}${index}`;
  }
  const defs = mapPreserve(doc.defs, (definition) =>
    definition.id === defId ? { ...definition, name: finalName } : definition,
  );
  if (defs === doc.defs) return doc;

  return rewriteRawDefinitionRefs(
    { ...doc, defs },
    currentDefinition.name,
    finalName,
  );
}

export function removeDefinition(
  doc: SchemaDocument,
  defId: string,
): SchemaDocument {
  const defs = doc.defs.filter((definition) => definition.id !== defId);
  if (defs.length === doc.defs.length) return doc;
  return { ...doc, defs };
}

export function setRef(
  doc: SchemaDocument,
  id: string,
  defId: string,
): SchemaDocument {
  return updateNode(doc, id, (node) => {
    if (isTypeArrayNullable(node)) {
      return {
        ...node,
        type: undefined,
        properties: undefined,
        items: undefined,
        enum: undefined,
        ref: undefined,
        rest: stripSchemaTypeSpecificRest(node.rest),
        order: undefined,
        anyOf: [createRefNode(defId), createNode("null")],
      };
    }

    return updateEffectiveNodeShape(node, (effective) => ({
      id: effective.id,
      ref: defId,
      title: effective.title,
      description: effective.description,
      rest: stripSchemaTypeSpecificRest(effective.rest),
      order: effective.order,
    }));
  });
}

export function setRefByName(
  doc: SchemaDocument,
  id: string,
  name: string,
): SchemaDocument {
  const definition = doc.defs.find((def) => def.name === name);
  return definition ? setRef(doc, id, definition.id) : doc;
}

function uniqueDefinitionName(doc: SchemaDocument, base: string): string {
  const taken = new Set(doc.defs.map((definition) => definition.name));
  if (!taken.has(base)) return base;
  let index = 2;
  while (taken.has(`${base}${index}`)) index += 1;
  return `${base}${index}`;
}

function isTypeArrayNullable(node: DocumentNode): boolean {
  return Array.isArray(node.type) && node.type.includes("null");
}

function createRefNode(defId: string): DocumentNode {
  return {
    id: createId(),
    ref: defId,
    rest: {},
  };
}

function rewriteRawDefinitionRefs(
  doc: SchemaDocument,
  oldName: string,
  newName: string,
): SchemaDocument {
  if (oldName === newName) return doc;

  const refs = getRewriteRefOptions(doc);
  const root = rewriteRawDefinitionRefsInNode(doc.root, oldName, newName, refs);
  const defs = mapPreserve(doc.defs, (definition) => {
    const node = rewriteRawDefinitionRefsInNode(
      definition.node,
      oldName,
      newName,
      refs,
    );
    return node === definition.node ? definition : { ...definition, node };
  });

  if (root === doc.root && defs === doc.defs) return doc;
  return { ...doc, root, defs };
}

function rewriteRawDefinitionRefsInNode(
  node: DocumentNode,
  oldName: string,
  newName: string,
  refs: RewriteRefOptions,
): DocumentNode {
  let next = node;

  const rest = rewriteRawDefinitionRefsInRest(
    node.rest,
    oldName,
    newName,
    refs,
  );
  if (rest !== node.rest) next = { ...next, rest };

  if (node.properties) {
    const properties = mapPreserve(node.properties, (property) => {
      const child = rewriteRawDefinitionRefsInNode(
        property.node,
        oldName,
        newName,
        refs,
      );
      return child === property.node ? property : { ...property, node: child };
    });
    if (properties !== node.properties) next = { ...next, properties };
  }

  if (node.items) {
    const items = rewriteRawDefinitionRefsInNode(
      node.items,
      oldName,
      newName,
      refs,
    );
    if (items !== node.items) next = { ...next, items };
  }

  for (const key of ["anyOf", "oneOf", "allOf"] as const) {
    const children = node[key];
    if (!children) continue;
    const mapped = mapPreserve(children, (child) =>
      rewriteRawDefinitionRefsInNode(child, oldName, newName, refs),
    );
    if (mapped !== children) next = { ...next, [key]: mapped };
  }

  return next;
}

function rewriteRawDefinitionRefsInRest(
  rest: Record<string, unknown>,
  oldName: string,
  newName: string,
  refs: RewriteRefOptions,
): Record<string, unknown> {
  let next = rest;

  for (const [key, value] of Object.entries(rest)) {
    const rewritten = SCHEMA_MAP_REST_KEYS.has(key)
      ? rewriteRefsInSchemaMap(value, oldName, newName, refs)
      : SCHEMA_VALUE_REST_KEYS.has(key)
        ? rewriteRefsInSchemaValue(value, oldName, newName, refs)
        : value;

    if (rewritten !== value) {
      if (next === rest) next = { ...rest };
      setRecordValue(next, key, rewritten);
    }
  }

  return next;
}

function rewriteRefsInSchemaMap(
  value: unknown,
  oldName: string,
  newName: string,
  refs: RewriteRefOptions,
): unknown {
  if (!isPlainObject(value)) return value;

  let next: Record<string, unknown> = value;
  for (const [key, child] of Object.entries(value)) {
    const rewritten = rewriteRefsInSchemaValue(child, oldName, newName, refs);
    if (rewritten !== child) {
      if (next === value) next = { ...value };
      setRecordValue(next, key, rewritten);
    }
  }
  return next;
}

function rewriteRefsInSchemaValue(
  value: unknown,
  oldName: string,
  newName: string,
  refs: RewriteRefOptions,
): unknown {
  if (Array.isArray(value)) {
    return mapPreserve(value, (child) =>
      rewriteRefsInSchemaValue(child, oldName, newName, refs),
    );
  }
  if (!isPlainObject(value)) return value;

  let next: Record<string, unknown> = value;
  const rewrittenRef = rewriteDefinitionRef(value.$ref, oldName, newName, refs);
  if (rewrittenRef !== value.$ref) {
    next = { ...value, $ref: rewrittenRef };
  }

  for (const [key, child] of Object.entries(next)) {
    let rewritten = child;
    if (SCHEMA_MAP_REST_KEYS.has(key)) {
      rewritten = rewriteRefsInSchemaMap(child, oldName, newName, refs);
    } else if (SCHEMA_VALUE_REST_KEYS.has(key)) {
      rewritten = rewriteRefsInSchemaValue(child, oldName, newName, refs);
    }

    if (rewritten !== child) {
      if (next === value) next = { ...value };
      setRecordValue(next, key, rewritten);
    }
  }

  return next;
}

function rewriteDefinitionRef(
  value: unknown,
  oldName: string,
  newName: string,
  refs: RewriteRefOptions,
): unknown {
  if (
    definitionRefAliases(refs.primaryKeyword, oldName).includes(value as string)
  )
    return definitionRef(refs.primaryKeyword, newName);
  if (
    refs.allowOtherKeywordAlias &&
    definitionRefAliases(refs.otherKeyword, oldName).includes(value as string)
  )
    return definitionRef(refs.otherKeyword, newName);
  return value;
}

interface RewriteRefOptions {
  primaryKeyword: "$defs" | "definitions";
  otherKeyword: "$defs" | "definitions";
  allowOtherKeywordAlias: boolean;
}

function getRewriteRefOptions(doc: SchemaDocument): RewriteRefOptions {
  const primaryKeyword =
    doc.rest.defsKeyword === "definitions" ? "definitions" : "$defs";
  const otherKeyword = primaryKeyword === "$defs" ? "definitions" : "$defs";
  return {
    primaryKeyword,
    otherKeyword,
    allowOtherKeywordAlias: !Object.prototype.hasOwnProperty.call(
      doc.root.rest,
      otherKeyword,
    ),
  };
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function setRecordValue<T>(record: Record<string, T>, key: string, value: T) {
  Object.defineProperty(record, key, {
    value,
    enumerable: true,
    configurable: true,
    writable: true,
  });
}

import type { JSONSchema7TypeName } from "json-schema";

import { definitionRefAliases } from "@/components/schema-editor/document/json-pointer";
import type {
  DefinitionEntry,
  DocumentNode,
  SchemaDocument,
  SchemaKind,
} from "./types";

const SCHEMA_VALUE_REST_KEYS = new Set([
  "additionalItems",
  "additionalProperties",
  "allOf",
  "anyOf",
  "contains",
  "else",
  "if",
  "items",
  "not",
  "oneOf",
  "prefixItems",
  "propertyNames",
  "then",
  "unevaluatedItems",
  "unevaluatedProperties",
]);

const SCHEMA_MAP_REST_KEYS = new Set([
  "$defs",
  "definitions",
  "dependentSchemas",
  "dependencies",
  "patternProperties",
  "properties",
]);

/**
 * Pure projections of a node for rendering. NONE of these are stored — there is
 * one source of truth (the Document) and these are computed on each render. This
 * is what lets child components stay stateless the way extend's do, without a
 * second representation to keep in sync.
 */

/** The effective UI "kind" of a node. */
export function getEffectiveKind(node: DocumentNode): SchemaKind {
  if (node.ref) return "ref";
  if (node.enum) return "enum";
  if (node.anyOf || node.oneOf) return "union";

  if (Array.isArray(node.type)) {
    const real = node.type.filter((t) => t !== "null");
    return real.length === 1 ? (real[0] as SchemaKind) : "union";
  }
  if (node.type) return node.type;
  return "any";
}

export function isNullable(node: DocumentNode): boolean {
  if (Array.isArray(node.type)) return node.type.includes("null");
  if (node.type === "null") return true;
  if (node.anyOf) return node.anyOf.some((sub) => sub.type === "null");
  return false;
}

/** Base scalar type backing an enum (enums are `{ type, enum: [...] }`). */
export function getEnumBaseType(node: DocumentNode): JSONSchema7TypeName {
  const type = Array.isArray(node.type)
    ? node.type.find((t) => t !== "null")
    : node.type;
  return (type as JSONSchema7TypeName) ?? "string";
}

/** Resolve a `$ref` node to the definition it points at (by id). */
export function resolveRef(
  doc: SchemaDocument,
  node: DocumentNode,
): DefinitionEntry | null {
  if (!node.ref) return null;
  return doc.defs.find((def) => def.id === node.ref) ?? null;
}

/** True when a `$ref` points at a definition that no longer exists. */
export function isDanglingRef(
  doc: SchemaDocument,
  node: DocumentNode,
): boolean {
  return Boolean(node.ref) && !resolveRef(doc, node);
}

export function isDefinitionReferenced(
  doc: SchemaDocument,
  defId: string,
  options: { exceptDefId?: string } = {},
): boolean {
  const referenced = doc.defs.find((definition) => definition.id === defId);
  if (!referenced) return false;

  const refs = getReferenceRefOptions(doc);

  if (nodeReferencesDefinition(doc.root, referenced, refs)) return true;

  for (const definition of doc.defs) {
    if (definition.id === options.exceptDefId) continue;
    if (nodeReferencesDefinition(definition.node, referenced, refs))
      return true;
  }

  return false;
}

function nodeReferencesDefinition(
  node: DocumentNode,
  definition: DefinitionEntry,
  refs: ReferenceRefOptions,
): boolean {
  if (node.ref === definition.id) return true;
  if (restReferencesDefinition(node.rest, definition, refs)) return true;

  if (node.properties) {
    for (const property of node.properties) {
      if (nodeReferencesDefinition(property.node, definition, refs))
        return true;
    }
  }

  if (node.items && nodeReferencesDefinition(node.items, definition, refs))
    return true;

  for (const key of ["anyOf", "oneOf", "allOf"] as const) {
    const children = node[key];
    if (!children) continue;
    for (const child of children) {
      if (nodeReferencesDefinition(child, definition, refs)) return true;
    }
  }

  return false;
}

function restReferencesDefinition(
  rest: Record<string, unknown>,
  definition: DefinitionEntry,
  refs: ReferenceRefOptions,
): boolean {
  for (const [key, value] of Object.entries(rest)) {
    if (SCHEMA_MAP_REST_KEYS.has(key)) {
      if (schemaMapReferencesDefinition(value, definition, refs)) return true;
    } else if (SCHEMA_VALUE_REST_KEYS.has(key)) {
      if (schemaReferencesDefinition(value, definition, refs)) return true;
    }
  }
  return false;
}

function schemaMapReferencesDefinition(
  value: unknown,
  definition: DefinitionEntry,
  refs: ReferenceRefOptions,
): boolean {
  if (!isPlainObject(value)) return false;
  return Object.values(value).some((child) =>
    schemaReferencesDefinition(child, definition, refs),
  );
}

function schemaReferencesDefinition(
  value: unknown,
  definition: DefinitionEntry,
  refs: ReferenceRefOptions,
): boolean {
  if (Array.isArray(value)) {
    return value.some((child) =>
      schemaReferencesDefinition(child, definition, refs),
    );
  }
  if (!isPlainObject(value)) return false;

  const ref = value.$ref;
  if (
    definitionRefAliases(refs.primaryKeyword, definition.name).includes(
      ref as string,
    )
  )
    return true;
  if (
    refs.allowOtherKeywordAlias &&
    definitionRefAliases(refs.otherKeyword, definition.name).includes(
      ref as string,
    )
  )
    return true;

  for (const [key, child] of Object.entries(value)) {
    if (SCHEMA_MAP_REST_KEYS.has(key)) {
      if (schemaMapReferencesDefinition(child, definition, refs)) return true;
    } else if (SCHEMA_VALUE_REST_KEYS.has(key)) {
      if (schemaReferencesDefinition(child, definition, refs)) return true;
    }
  }

  return false;
}

interface ReferenceRefOptions {
  primaryKeyword: "$defs" | "definitions";
  otherKeyword: "$defs" | "definitions";
  allowOtherKeywordAlias: boolean;
}

function getReferenceRefOptions(doc: SchemaDocument): ReferenceRefOptions {
  const primaryKeyword =
    doc.rest.defsKeyword === "definitions" ? "definitions" : "$defs";
  const otherKeyword = primaryKeyword === "$defs" ? "definitions" : "$defs";
  return {
    primaryKeyword,
    otherKeyword,
    allowOtherKeywordAlias: !Object.prototype.hasOwnProperty.call(
      doc.root.rest,
      otherKeyword,
    ),
  };
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

import { mapPreserve } from "@/components/schema-editor/document/array";
import { getEffectiveDocNode } from "@/components/schema-editor/document/node-selectors";
import { updateNode } from "@/components/schema-editor/document/node-update";
import { getNode } from "@/components/schema-editor/document/traversal";
import {
  createNode,
  createEnumValue,
  stripSchemaTypeSpecificRest,
  updateEffectiveNodeShape,
} from "@/components/schema-editor/document/type-operations";
import type {
  DocumentNode,
  EnumValue,
  JsonValue,
  SchemaDocument,
} from "@/components/schema-editor/document/types";

const ENUM_DESCRIPTIONS_KEY = "x-enumDescriptions";

export function addEnumValue(
  doc: SchemaDocument,
  id: string,
  value: JsonValue = "",
): SchemaDocument {
  return updateNode(doc, id, (node) => {
    if (isTypeArrayNullable(node) && node.enum) {
      const nextEnum = [...node.enum, { ...createEnumValue(), value }];
      return createNullableEnumWrapper(
        node,
        nextEnum,
        remapEnumDescriptions(node.rest, node.enum, nextEnum),
      );
    }

    return updateEffectiveNodeShape(node, (effective) => {
      const previousEnum = effective.enum ?? [];
      const nextEnum = [...previousEnum, { ...createEnumValue(), value }];

      return {
        ...effective,
        enum: nextEnum,
        rest: remapEnumDescriptions(effective.rest, previousEnum, nextEnum),
      };
    });
  });
}

export function updateEnumValue(
  doc: SchemaDocument,
  id: string,
  enumId: string,
  patch: Partial<Omit<EnumValue, "id">>,
): SchemaDocument {
  return updateNode(doc, id, (node) => {
    if (isTypeArrayNullable(node) && node.enum) {
      const nextEnum = mapPreserve(node.enum, (value) =>
        value.id === enumId ? { ...value, ...patch } : value,
      );
      return createNullableEnumWrapper(
        node,
        nextEnum,
        remapEnumDescriptions(node.rest, node.enum, nextEnum),
      );
    }

    return updateEffectiveNodeShape(node, (effective) => {
      const previousEnum = effective.enum ?? [];
      const nextEnum = mapPreserve(previousEnum, (value) =>
        value.id === enumId ? { ...value, ...patch } : value,
      );

      return {
        ...effective,
        enum: nextEnum,
        rest: remapEnumDescriptions(effective.rest, previousEnum, nextEnum),
      };
    });
  });
}

export function removeEnumValue(
  doc: SchemaDocument,
  id: string,
  enumId: string,
): SchemaDocument {
  return updateNode(doc, id, (node) => {
    if (isTypeArrayNullable(node) && node.enum) {
      const nextEnum = node.enum.filter((value) => value.id !== enumId);
      return createNullableEnumWrapper(
        node,
        nextEnum,
        remapEnumDescriptions(node.rest, node.enum, nextEnum),
      );
    }

    return updateEffectiveNodeShape(node, (effective) => {
      const previousEnum = effective.enum ?? [];
      const nextEnum = previousEnum.filter((value) => value.id !== enumId);

      return {
        ...effective,
        enum: nextEnum,
        rest: remapEnumDescriptions(effective.rest, previousEnum, nextEnum),
      };
    });
  });
}

export function setEnumValues(
  doc: SchemaDocument,
  id: string,
  values: JsonValue[],
): SchemaDocument {
  return updateNode(doc, id, (node) => {
    if (isTypeArrayNullable(node)) {
      const nextEnum = buildEnumValues(values, node.enum);
      return createNullableEnumWrapper(
        node,
        nextEnum,
        remapEnumDescriptions(node.rest, node.enum, nextEnum),
      );
    }

    return updateEffectiveNodeShape(node, (effective) => {
      const nextEnum = buildEnumValues(values, effective.enum);
      const rest = stripSchemaRestForEnum(
        remapEnumDescriptions(effective.rest, effective.enum, nextEnum),
      );
      return {
        ...effective,
        type: "string",
        enum: nextEnum,
        rest,
        booleanSchema: undefined,
      };
    });
  });
}

export function updateEnumValueAtIndex(
  doc: SchemaDocument,
  id: string,
  index: number,
  value: JsonValue,
): SchemaDocument {
  const node = getNode(doc, id);
  if (!node) return doc;

  const enumId = getEffectiveDocNode(node).enum?.[index]?.id;
  return enumId ? updateEnumValue(doc, id, enumId, { value }) : doc;
}

export function removeEnumValueAtIndex(
  doc: SchemaDocument,
  id: string,
  index: number,
): SchemaDocument {
  const node = getNode(doc, id);
  if (!node) return doc;

  const enumId = getEffectiveDocNode(node).enum?.[index]?.id;
  return enumId ? removeEnumValue(doc, id, enumId) : doc;
}

function buildEnumValues(
  values: JsonValue[],
  existing?: EnumValue[],
): EnumValue[] {
  return values.map((value, index) => ({
    ...(existing?.[index] ?? createEnumValue()),
    value,
  }));
}

function isTypeArrayNullable(node: DocumentNode): boolean {
  return Array.isArray(node.type) && node.type.includes("null");
}

function createEnumNode(
  values: JsonValue[],
  existing?: EnumValue[],
): DocumentNode {
  return createEnumNodeFromEntries(buildEnumValues(values, existing));
}

function createEnumNodeFromEntries(enumEntries: EnumValue[]): DocumentNode {
  const node = createNode("string");
  return {
    ...node,
    type: "string",
    enum: enumEntries,
  };
}

function createNullableEnumWrapper(
  node: DocumentNode,
  enumEntries: EnumValue[],
  rest: Record<string, unknown> = node.rest,
): DocumentNode {
  return {
    ...node,
    type: undefined,
    properties: undefined,
    items: undefined,
    enum: undefined,
    ref: undefined,
    rest: stripSchemaRestForEnum(rest),
    order: undefined,
    booleanSchema: undefined,
    anyOf: [createEnumNodeFromEntries(enumEntries), { ...createNode("null") }],
  };
}

function stripSchemaRestForEnum(
  rest: Record<string, unknown>,
): Record<string, unknown> {
  const descriptions = rest[ENUM_DESCRIPTIONS_KEY];
  const next = { ...stripSchemaTypeSpecificRest(rest) };
  if (isPlainRecord(descriptions)) {
    next[ENUM_DESCRIPTIONS_KEY] = descriptions;
  }
  return next;
}

function remapEnumDescriptions(
  rest: Record<string, unknown>,
  previousEntries: EnumValue[] | undefined,
  nextEntries: EnumValue[],
): Record<string, unknown> {
  const descriptions = rest[ENUM_DESCRIPTIONS_KEY];
  if (!isPlainRecord(descriptions)) return rest;

  const previousById = new Map(
    previousEntries?.map((entry) => [entry.id, entry]) ?? [],
  );
  const nextDescriptions: Record<string, unknown> = {};
  for (let index = 0; index < nextEntries.length; index += 1) {
    const nextEntry = nextEntries[index];
    const previous = previousById.get(nextEntry.id) ?? previousEntries?.[index];
    if (!previous) continue;
    const previousKey = enumDescriptionKey(previous.value);
    if (!hasOwn(descriptions, previousKey)) continue;
    nextDescriptions[enumDescriptionKey(nextEntry.value)] =
      descriptions[previousKey];
  }

  const next = { ...rest };
  if (Object.keys(nextDescriptions).length > 0) {
    next[ENUM_DESCRIPTIONS_KEY] = nextDescriptions;
  } else {
    delete next[ENUM_DESCRIPTIONS_KEY];
  }
  return next;
}

function enumDescriptionKey(value: JsonValue): string {
  return String(value);
}

function isPlainRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function hasOwn(record: Record<string, unknown>, key: string): boolean {
  return Object.prototype.hasOwnProperty.call(record, key);
}

import type { NodeId } from "./types";

/**
 * Monotonic id minting. Ids are minted exactly once per node — at creation, or at
 * the import boundary when an external JSON Schema first becomes a Document — and
 * are stable for the node's lifetime thereafter.
 *
 * A module-level counter (rather than a random uuid) keeps ids short and stable
 * for snapshot tests; it is process-local, which is all the editor needs since
 * ids never have to be reconstructed from a serialized form (JSON Schema carries
 * none — that asymmetry is the point).
 */
let counter = 0;

export function createId(prefix = "node"): NodeId {
  counter += 1;
  return `${prefix}-${counter}`;
}

import type { JSONSchema7Definition } from "json-schema";

import {
  nodeFromJson,
  projectNode,
} from "@/components/schema-editor/document/convert";
import { updateNode } from "@/components/schema-editor/document/node-update";
import { getNode } from "@/components/schema-editor/document/traversal";
import type { SchemaDocument } from "@/components/schema-editor/document/types";

export function getNodeJson(
  doc: SchemaDocument,
  id: string,
): JSONSchema7Definition | null {
  const node = getNode(doc, id);
  return node ? projectNode(doc, node) : null;
}

export function replaceNodeJson(
  doc: SchemaDocument,
  id: string,
  jsonNode: JSONSchema7Definition,
): SchemaDocument {
  const converted = nodeFromJson(jsonNode, doc);
  return updateNode(doc, id, (node) => ({
    ...converted,
    id: node.id,
    order: node.order ?? converted.order,
  }));
}

export function updateNodeJson(
  doc: SchemaDocument,
  id: string,
  transform: (json: JSONSchema7Definition) => JSONSchema7Definition,
): SchemaDocument {
  const json = getNodeJson(doc, id);
  if (json === null) return doc;
  return replaceNodeJson(doc, id, transform(json));
}

export type DefinitionsKeyword = "$defs" | "definitions";

export function escapeJsonPointerSegment(segment: string): string {
  return segment.replace(/~/g, "~0").replace(/\//g, "~1");
}

export function unescapeJsonPointerSegment(segment: string): string {
  return segment.replace(/~1/g, "/").replace(/~0/g, "~");
}

export function decodeJsonPointerSegment(segment: string): string {
  return unescapeJsonPointerSegment(decodeUriComponentSafe(segment));
}

export function definitionRef(
  keyword: DefinitionsKeyword,
  name: string,
): string {
  return `#/${keyword}/${escapeJsonPointerSegment(name)}`;
}

export function definitionRefAliases(
  keyword: DefinitionsKeyword,
  name: string,
): string[] {
  const pointerSegment = escapeJsonPointerSegment(name);
  const encodedSegment = encodeURIComponent(pointerSegment);
  const encodedNameSegment = encodeURIComponent(name);
  const encodedNameSegmentWithTilde = encodedNameSegment.replace(/~/g, "%7E");
  const lowerHexEncodedSegment = encodedSegment.replace(
    /%[0-9A-F]{2}/g,
    (escapeSequence) => escapeSequence.toLowerCase(),
  );
  const lowerHexEncodedNameSegment = encodedNameSegmentWithTilde.replace(
    /%[0-9A-F]{2}/g,
    (escapeSequence) => escapeSequence.toLowerCase(),
  );
  return [
    ...new Set([
      `#/${keyword}/${pointerSegment}`,
      `#/${keyword}/${encodedSegment}`,
      `#/${keyword}/${lowerHexEncodedSegment}`,
      ...encodedOriginalNameAliases(keyword, encodedNameSegment),
      ...encodedOriginalNameAliases(keyword, encodedNameSegmentWithTilde),
      ...encodedOriginalNameAliases(keyword, lowerHexEncodedNameSegment),
    ]),
  ];
}

function encodedOriginalNameAliases(
  keyword: DefinitionsKeyword,
  encodedSegment: string,
): string[] {
  return encodedSegment.includes("%") ? [`#/${keyword}/${encodedSegment}`] : [];
}

export function definitionNameFromRef(ref: string): string {
  const prefix = ref.startsWith("#/$defs/")
    ? "#/$defs/"
    : ref.startsWith("#/definitions/")
      ? "#/definitions/"
      : undefined;
  return prefix ? decodeJsonPointerSegment(ref.slice(prefix.length)) : ref;
}

function decodeUriComponentSafe(value: string): string {
  try {
    return decodeURIComponent(value);
  } catch {
    return value;
  }
}

import { mapPreserve } from "@/components/schema-editor/document/array";
import { updateNode } from "@/components/schema-editor/document/node-update";
import type {
  DocumentNode,
  SchemaDocument,
} from "@/components/schema-editor/document/types";

const SCHEMA_VALUE_REST_KEYS = new Set([
  "additionalItems",
  "additionalProperties",
  "allOf",
  "anyOf",
  "contains",
  "else",
  "if",
  "items",
  "not",
  "oneOf",
  "prefixItems",
  "propertyNames",
  "then",
  "unevaluatedItems",
  "unevaluatedProperties",
]);

const SCHEMA_MAP_REST_KEYS = new Set([
  "$defs",
  "definitions",
  "dependentSchemas",
  "dependencies",
  "patternProperties",
  "properties",
]);

export function setNodeDescription(
  doc: SchemaDocument,
  id: string,
  description: string | undefined,
): SchemaDocument {
  return updateNode(doc, id, (node) => {
    const nextDescription = description?.trim() ? description : undefined;
    return node.description === nextDescription
      ? node
      : { ...node, description: nextDescription };
  });
}

export function setNodeTitle(
  doc: SchemaDocument,
  id: string,
  title: string | undefined,
): SchemaDocument {
  return updateNode(doc, id, (node) => {
    const nextTitle = title?.trim() ? title : undefined;
    return node.title === nextTitle ? node : { ...node, title: nextTitle };
  });
}

export function stripDescriptions(doc: SchemaDocument): SchemaDocument {
  const root = stripNodeDescription(doc.root);
  const defs = mapPreserve(doc.defs, (definition) => {
    const node = stripNodeDescription(definition.node);
    return node === definition.node ? definition : { ...definition, node };
  });
  if (root === doc.root && defs === doc.defs) return doc;
  return { ...doc, root, defs };
}

function stripNodeDescription(node: DocumentNode): DocumentNode {
  let next =
    node.description === undefined ? node : { ...node, description: undefined };

  if (next.properties) {
    const properties = mapPreserve(next.properties, (property) => {
      const childNode = stripNodeDescription(property.node);
      return childNode === property.node
        ? property
        : { ...property, node: childNode };
    });
    if (properties !== next.properties) next = { ...next, properties };
  }

  const rest = stripRestDescriptionKeywords(next.rest);
  if (rest !== next.rest) next = { ...next, rest };

  if (next.items) {
    const items = stripNodeDescription(next.items);
    if (items !== next.items) next = { ...next, items };
  }

  for (const key of ["anyOf", "oneOf", "allOf"] as const) {
    const children = next[key];
    if (!children) continue;
    const mapped = mapPreserve(children, stripNodeDescription);
    if (mapped !== children) next = { ...next, [key]: mapped };
  }

  return next;
}

function stripRestDescriptionKeywords(
  rest: Record<string, unknown>,
): Record<string, unknown> {
  let next = rest;

  for (const [key, value] of Object.entries(rest)) {
    const stripped = SCHEMA_MAP_REST_KEYS.has(key)
      ? stripSchemaMapDescriptions(value)
      : SCHEMA_VALUE_REST_KEYS.has(key)
        ? stripSchemaDescription(value)
        : value;

    if (stripped !== value) {
      if (next === rest) next = { ...rest };
      setRecordValue(next, key, stripped);
    }
  }

  return next;
}

function stripSchemaMapDescriptions(value: unknown): unknown {
  if (!isPlainObject(value)) return value;

  let next: Record<string, unknown> = value;
  for (const [key, child] of Object.entries(value)) {
    const stripped = stripSchemaDescription(child);
    if (stripped !== child) {
      if (next === value) next = { ...value };
      setRecordValue(next, key, stripped);
    }
  }

  return next;
}

function stripSchemaDescription(value: unknown): unknown {
  if (Array.isArray(value)) {
    return mapPreserve(value, stripSchemaDescription);
  }
  if (!isPlainObject(value)) return value;

  let next: Record<string, unknown> = value;
  if (Object.prototype.hasOwnProperty.call(value, "description")) {
    const { description: _description, ...rest } = value;
    next = rest;
  }

  for (const [key, child] of Object.entries(next)) {
    let stripped = child;
    if (SCHEMA_MAP_REST_KEYS.has(key)) {
      stripped = stripSchemaMapDescriptions(child);
    } else if (SCHEMA_VALUE_REST_KEYS.has(key)) {
      stripped = stripSchemaDescription(child);
    }

    if (stripped !== child) {
      if (next === value) next = { ...value };
      setRecordValue(next, key, stripped);
    }
  }

  return next;
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function setRecordValue<T>(record: Record<string, T>, key: string, value: T) {
  Object.defineProperty(record, key, {
    value,
    enumerable: true,
    configurable: true,
    writable: true,
  });
}

import { getNode } from "@/components/schema-editor/document/traversal";
import type {
  DocumentNode,
  PropertyEntry,
  SchemaDocument,
} from "@/components/schema-editor/document/types";

export function getEffectiveDocNode(node: DocumentNode): DocumentNode {
  if (node.anyOf) {
    const nonNull = node.anyOf.find(
      (branch) => branch.type !== "null" || branch.ref,
    );
    if (nonNull) return nonNull;
  }
  return node;
}

export function getChildPropertyId(
  doc: SchemaDocument,
  parentId: string,
  key: string,
): string | undefined {
  const parent = getNode(doc, parentId);
  if (!parent) return undefined;
  return getEffectiveDocNode(parent).properties?.find(
    (entry) => entry.key === key,
  )?.id;
}

export function getChildNodeId(
  doc: SchemaDocument,
  parentId: string,
  key: string,
): string | undefined {
  const parent = getNode(doc, parentId);
  if (!parent) return undefined;
  return getEffectiveDocNode(parent).properties?.find(
    (entry) => entry.key === key,
  )?.node.id;
}

export function getItemsNodeId(
  doc: SchemaDocument,
  parentId: string,
): string | undefined {
  const parent = getNode(doc, parentId);
  if (!parent) return undefined;
  return getEffectiveDocNode(parent).items?.id;
}

export function getOwnProperty(
  doc: SchemaDocument,
  parentId: string,
  index: number,
): PropertyEntry | null {
  const parent = getNode(doc, parentId);
  return parent
    ? (getEffectiveDocNode(parent).properties?.[index] ?? null)
    : null;
}

import { mapPreserve } from "@/components/schema-editor/document/array";
import type {
  DocumentNode,
  SchemaDocument,
} from "@/components/schema-editor/document/types";

export function updateNode(
  doc: SchemaDocument,
  id: string,
  fn: (node: DocumentNode) => DocumentNode,
): SchemaDocument {
  const root = replaceInNode(doc.root, id, fn);
  const defs = mapPreserve(doc.defs, (definition) => {
    const node = replaceInNode(definition.node, id, fn);
    return node === definition.node ? definition : { ...definition, node };
  });
  if (root === doc.root && defs === doc.defs) return doc;
  return { ...doc, root, defs };
}

function replaceInNode(
  node: DocumentNode,
  id: string,
  fn: (node: DocumentNode) => DocumentNode,
): DocumentNode {
  if (node.id === id) return fn(node);

  let next = node;

  if (node.properties) {
    const properties = mapPreserve(node.properties, (entry) => {
      const child = replaceInNode(entry.node, id, fn);
      return child === entry.node ? entry : { ...entry, node: child };
    });
    if (properties !== node.properties) next = { ...next, properties };
  }

  if (node.items) {
    const items = replaceInNode(node.items, id, fn);
    if (items !== node.items) next = { ...next, items };
  }

  for (const key of ["anyOf", "oneOf", "allOf"] as const) {
    const list = node[key];
    if (!list) continue;
    const mapped = mapPreserve(list, (child) => replaceInNode(child, id, fn));
    if (mapped !== list) next = { ...next, [key]: mapped };
  }

  return next;
}

export function updateNodeRest(
  doc: SchemaDocument,
  id: string,
  patch: Record<string, unknown>,
): SchemaDocument {
  return updateNode(doc, id, (node) => ({
    ...node,
    rest: { ...node.rest, ...patch },
  }));
}

import { mapPreserve } from "@/components/schema-editor/document/array";
import { createId } from "@/components/schema-editor/document/id";
import {
  getEffectiveDocNode,
  getOwnProperty,
} from "@/components/schema-editor/document/node-selectors";
import { updateNode } from "@/components/schema-editor/document/node-update";
import {
  childNodes,
  getNode,
} from "@/components/schema-editor/document/traversal";
import { createNode } from "@/components/schema-editor/document/type-operations";
import type {
  DocumentNode,
  PropertyEntry,
  SchemaDocument,
} from "@/components/schema-editor/document/types";

function updateObjectProperties(
  doc: SchemaDocument,
  parentId: string,
  fn: (properties: PropertyEntry[]) => PropertyEntry[],
): SchemaDocument {
  return updateNode(doc, parentId, (node) => {
    if (isSingleNullableBranchContainer(node)) {
      const branch = getEffectiveDocNode(node);
      if (branch.type !== "object" && !branch.properties) return node;
      return {
        ...node,
        anyOf: node.anyOf!.map((child) =>
          child.id === branch.id
            ? updateNodeProperties(child, fn(child.properties ?? []))
            : child,
        ),
      };
    }

    if (node.type !== "object" && !node.properties) return node;
    return updateNodeProperties(node, fn(node.properties ?? []));
  });
}

function updateNodeProperties(
  node: DocumentNode,
  properties: PropertyEntry[],
): DocumentNode {
  return {
    ...node,
    properties,
    requiredOrder: getRequiredOrder(node, properties),
  };
}

function getRequiredOrder(
  node: DocumentNode,
  properties: PropertyEntry[],
): string[] | undefined {
  const requiredProperties = properties
    .filter((property) => property.required && isProjectableProperty(property))
    .map((property) => property.key);
  const extraRequired = node.extraRequired ?? [];

  if (requiredProperties.length === 0 && extraRequired.length === 0) {
    return node.requiredOrder?.length ? [] : undefined;
  }

  const orderedExtraRequired = node.requiredOrder
    ? node.requiredOrder.filter((name) => extraRequired.includes(name))
    : extraRequired;

  return [...orderedExtraRequired, ...requiredProperties];
}

export function findOwningProperty(
  doc: SchemaDocument,
  propertyId: string,
): { parentId: string; index: number } | null {
  let result: { parentId: string; index: number } | null = null;
  const visit = (node: DocumentNode) => {
    if (result) return;
    if (node.properties) {
      const index = node.properties.findIndex(
        (property) => property.id === propertyId,
      );
      if (index >= 0) {
        result = { parentId: node.id, index };
        return;
      }
    }
    for (const child of childNodes(node)) visit(child);
  };
  visit(doc.root);
  for (const definition of doc.defs) visit(definition.node);
  return result;
}

export function addProperty(
  doc: SchemaDocument,
  parentId: string,
  init: Partial<PropertyEntry> = {},
): SchemaDocument {
  const entry: PropertyEntry = {
    id: init.id ?? createId("prop"),
    key: init.key ?? "",
    isTransient: init.isTransient ?? (init.key ? undefined : true),
    required: init.required ?? false,
    node: init.node ?? createNode("string"),
  };
  return updateObjectProperties(doc, parentId, (properties) => [
    ...properties,
    entry,
  ]);
}

export function removeProperty(
  doc: SchemaDocument,
  propertyId: string,
): SchemaDocument {
  const owner = findOwningProperty(doc, propertyId);
  if (!owner) return doc;
  return updateObjectProperties(doc, owner.parentId, (properties) =>
    properties.filter((property) => property.id !== propertyId),
  );
}

export function renameProperty(
  doc: SchemaDocument,
  propertyId: string,
  key: string,
): SchemaDocument {
  return updateOwningEntry(doc, propertyId, (entry) =>
    entry.key === key
      ? entry
      : { ...entry, key, isTransient: key === "" ? true : undefined },
  );
}

export function setRequired(
  doc: SchemaDocument,
  propertyId: string,
  required: boolean,
): SchemaDocument {
  return updateOwningEntry(doc, propertyId, (entry) =>
    entry.required === required ? entry : { ...entry, required },
  );
}

function updateOwningEntry(
  doc: SchemaDocument,
  propertyId: string,
  fn: (entry: PropertyEntry) => PropertyEntry,
): SchemaDocument {
  const owner = findOwningProperty(doc, propertyId);
  if (!owner) return doc;
  return updateObjectProperties(doc, owner.parentId, (properties) =>
    mapPreserve(properties, (entry) =>
      entry.id === propertyId ? fn(entry) : entry,
    ),
  );
}

export function moveProperty(
  doc: SchemaDocument,
  propertyId: string,
  targetParentId: string,
  index: number,
): SchemaDocument {
  const owner = findOwningProperty(doc, propertyId);
  if (!owner) return doc;
  const moved = getOwnProperty(doc, owner.parentId, owner.index);
  if (!moved) return doc;
  const targetParent = getNode(doc, targetParentId);
  if (!targetParent) return doc;
  const targetEffectiveParent = getEffectiveDocNode(targetParent);
  if (
    targetEffectiveParent.type !== "object" &&
    !targetEffectiveParent.properties
  )
    return doc;

  if (isAncestor(doc, moved.node.id, targetParentId)) return doc;

  let next = updateObjectProperties(doc, owner.parentId, (properties) =>
    properties.filter((property) => property.id !== propertyId),
  );
  next = updateObjectProperties(next, targetParentId, (properties) => {
    const clamped = Math.max(0, Math.min(index, properties.length));
    const out = properties.slice();
    out.splice(clamped, 0, moved);
    return out;
  });
  return next;
}

function isSingleNullableBranchContainer(node: DocumentNode): boolean {
  if (!node.anyOf) return false;
  const nonNullBranches = node.anyOf.filter(
    (branch) => branch.type !== "null" || branch.ref,
  );
  return (
    nonNullBranches.length === 1 &&
    node.anyOf.length === 2 &&
    node.anyOf.some((branch) => branch.type === "null" && !branch.ref)
  );
}

function isProjectableProperty(property: PropertyEntry): boolean {
  return property.key !== "" || !property.isTransient;
}

function isAncestor(
  doc: SchemaDocument,
  nodeId: string,
  maybeDescendantId: string,
): boolean {
  const node = getNode(doc, nodeId);
  if (!node) return false;
  if (node.id === maybeDescendantId) return true;
  return childNodes(node).some((child) =>
    isAncestor(doc, child.id, maybeDescendantId),
  );
}

import type {
  DefinitionEntry,
  DocumentNode,
  SchemaDocument,
} from "@/components/schema-editor/document/types";

export function childNodes(node: DocumentNode): DocumentNode[] {
  const out: DocumentNode[] = [];
  if (node.properties)
    for (const property of node.properties) out.push(property.node);
  if (node.items) out.push(node.items);
  if (node.anyOf) out.push(...node.anyOf);
  if (node.oneOf) out.push(...node.oneOf);
  if (node.allOf) out.push(...node.allOf);
  return out;
}

export function getNode(doc: SchemaDocument, id: string): DocumentNode | null {
  return findInNode(doc.root, id) ?? findInDefinitions(doc.defs, id);
}

function findInDefinitions(
  definitions: DefinitionEntry[],
  id: string,
): DocumentNode | null {
  for (const definition of definitions) {
    const found = findInNode(definition.node, id);
    if (found) return found;
  }
  return null;
}

function findInNode(node: DocumentNode, id: string): DocumentNode | null {
  if (node.id === id) return node;
  for (const child of childNodes(node)) {
    const found = findInNode(child, id);
    if (found) return found;
  }
  return null;
}

export function findNodeByPath(
  doc: SchemaDocument,
  path: string | readonly string[],
): string | null {
  const segments =
    typeof path === "string" ? path.split(".").filter(Boolean) : path;
  let node: DocumentNode | undefined = doc.root;
  for (const segment of segments) {
    node = unwrapContainer(doc, node);
    const entry = node?.properties?.find(
      (property) => property.key === segment,
    );
    if (!entry) return null;
    node = entry.node;
  }
  return node?.id ?? null;
}

function unwrapContainer(
  doc: SchemaDocument,
  node: DocumentNode | undefined,
): DocumentNode | undefined {
  let current = node;
  const visited = new Set<string>();
  while (current) {
    current = getEffectiveContainerNode(current);
    if (visited.has(current.id)) return undefined;
    visited.add(current.id);
    if (current.ref) {
      current = doc.defs.find(
        (definition) => definition.id === current!.ref,
      )?.node;
      continue;
    }
    if (current.items && !current.properties) {
      current = current.items;
      continue;
    }
    break;
  }
  return current;
}

function getEffectiveContainerNode(node: DocumentNode): DocumentNode {
  if (node.anyOf) {
    const nonNull = node.anyOf.find(
      (branch) => branch.type !== "null" || branch.ref,
    );
    if (nonNull) return nonNull;
  }
  return node;
}

import type { JSONSchema7TypeName } from "json-schema";

import { mapPreserve } from "@/components/schema-editor/document/array";
import { createId } from "@/components/schema-editor/document/id";
import { updateNode } from "@/components/schema-editor/document/node-update";
import type {
  DocumentNode,
  EnumValue,
  SchemaDocument,
} from "@/components/schema-editor/document/types";

export type SchemaEditorType =
  | JSONSchema7TypeName
  | "enum"
  | "date"
  | "time"
  | "datetime";

const STRING_REST_KEYS = new Set([
  "contentEncoding",
  "contentMediaType",
  "contentSchema",
  "format",
  "maxLength",
  "minLength",
  "pattern",
]);

const NUMBER_REST_KEYS = new Set([
  "exclusiveMaximum",
  "exclusiveMinimum",
  "maximum",
  "minimum",
  "multipleOf",
]);

const ARRAY_REST_KEYS = new Set([
  "additionalItems",
  "contains",
  "items",
  "maxContains",
  "maxItems",
  "minContains",
  "minItems",
  "prefixItems",
  "unevaluatedItems",
  "uniqueItems",
]);

const OBJECT_REST_KEYS = new Set([
  "additionalProperties",
  "dependentRequired",
  "dependentSchemas",
  "dependencies",
  "maxProperties",
  "minProperties",
  "patternProperties",
  "propertyNames",
  "unevaluatedProperties",
]);

const ENUM_REST_KEYS = new Set(["x-enumDescriptions"]);

const ENUM_ALLOWED_REST_KEYS = new Set([
  ...STRING_REST_KEYS,
  ...ENUM_REST_KEYS,
]);

const TYPE_SPECIFIC_REST_KEYS = new Set([
  ...STRING_REST_KEYS,
  ...NUMBER_REST_KEYS,
  ...ARRAY_REST_KEYS,
  ...OBJECT_REST_KEYS,
  ...ENUM_REST_KEYS,
]);

export function setNodeType(
  doc: SchemaDocument,
  id: string,
  type: JSONSchema7TypeName | "enum",
): SchemaDocument {
  return updateNode(doc, id, (node) => normalizeNodeForType(node, type));
}

export function setNodeEditorType(
  doc: SchemaDocument,
  id: string,
  type: SchemaEditorType,
): SchemaDocument {
  return updateNode(doc, id, (node) =>
    updateEffectiveNodeShape(node, (effective) =>
      normalizeNodeForEditorType(effective, type),
    ),
  );
}

export function normalizeNodeForType(
  node: DocumentNode,
  type: JSONSchema7TypeName | "enum",
): DocumentNode {
  const nullable = isNodeNullable(node);
  const base: DocumentNode = {
    ...node,
    rest: stripSchemaRestForType(node.rest, type),
    ref: undefined,
    anyOf: undefined,
    oneOf: undefined,
    allOf: undefined,
    properties: undefined,
    extraRequired: undefined,
    requiredOrder: undefined,
    items: undefined,
    enum: undefined,
    booleanSchema: undefined,
  };

  if (type === "enum") {
    base.type = "string";
    base.enum = node.enum?.length ? node.enum : [createEnumValue()];
  } else if (type === "object") {
    base.type = "object";
    base.extraRequired = node.extraRequired;
    base.requiredOrder = node.requiredOrder;
    base.properties = node.properties?.length
      ? node.properties
      : [
          {
            id: createId("prop"),
            key: "",
            // Starter row the user has yet to name: mark it transient so the
            // empty key is dropped at the projection boundary (matching
            // `addProperty`) instead of leaking as a property named "".
            isTransient: true,
            required: false,
            node: createNode("string"),
          },
        ];
  } else if (type === "array") {
    base.type = "array";
    base.items = node.items ?? createNode("string");
  } else {
    base.type = type;
  }

  return nullable ? setNodeNullable(base, true) : base;
}

function normalizeNodeForEditorType(
  node: DocumentNode,
  type: SchemaEditorType,
): DocumentNode {
  const format =
    type === "date"
      ? "date"
      : type === "time"
        ? "time"
        : type === "datetime"
          ? "date-time"
          : undefined;
  const schemaType: JSONSchema7TypeName | "enum" = format
    ? "string"
    : (type as JSONSchema7TypeName | "enum");
  const normalized = normalizeNodeForType(node, schemaType);

  return {
    ...normalized,
    rest: format
      ? { ...stripSchemaFormat(normalized.rest), format }
      : stripSchemaFormat(normalized.rest),
  };
}

export function stripSchemaFormat(
  rest: Record<string, unknown>,
): Record<string, unknown> {
  if (!Object.prototype.hasOwnProperty.call(rest, "format")) return rest;
  const { format: _format, ...withoutFormat } = rest;
  return withoutFormat;
}

export function stripSchemaTypeSpecificRest(
  rest: Record<string, unknown>,
): Record<string, unknown> {
  return filterSchemaRest(rest, undefined);
}

function stripSchemaRestForType(
  rest: Record<string, unknown>,
  type: JSONSchema7TypeName | "enum",
): Record<string, unknown> {
  return filterSchemaRest(rest, getRestKeysForType(type));
}

function getRestKeysForType(
  type: JSONSchema7TypeName | "enum",
): Set<string> | undefined {
  if (type === "string") return STRING_REST_KEYS;
  if (type === "enum") return ENUM_ALLOWED_REST_KEYS;
  if (type === "number" || type === "integer") return NUMBER_REST_KEYS;
  if (type === "array") return ARRAY_REST_KEYS;
  if (type === "object") return OBJECT_REST_KEYS;
  return undefined;
}

function filterSchemaRest(
  rest: Record<string, unknown>,
  allowedTypeSpecificKeys: Set<string> | undefined,
): Record<string, unknown> {
  let next = rest;

  for (const key of Object.keys(rest)) {
    if (
      TYPE_SPECIFIC_REST_KEYS.has(key) &&
      !allowedTypeSpecificKeys?.has(key)
    ) {
      if (next === rest) next = { ...rest };
      delete next[key];
    }
  }

  return next;
}

export function setNullable(
  doc: SchemaDocument,
  id: string,
  nullable: boolean,
): SchemaDocument {
  return updateNode(doc, id, (node) => setNodeNullable(node, nullable));
}

function setNodeNullable(node: DocumentNode, nullable: boolean): DocumentNode {
  if (node.anyOf) {
    return setAnyOfNodeNullable(node, nullable);
  }

  const current = node.type;
  const names = Array.isArray(current)
    ? current.filter((type) => type !== "null")
    : current
      ? [current]
      : [];

  if (nullable) {
    if (node.enum) return wrapNodeInNullableAnyOf(node);
    if (names.length === 0) {
      return node.ref ? wrapNodeInNullableAnyOf(node) : node;
    }
    return { ...node, type: [...names, "null"] };
  }

  if (names.length <= 1) return { ...node, type: names[0] };
  return { ...node, type: names };
}

function isNodeNullable(node: DocumentNode): boolean {
  if (Array.isArray(node.type)) return node.type.includes("null");
  if (node.anyOf) return node.anyOf.some((branch) => branch.type === "null");
  return node.type === "null";
}

function setAnyOfNodeNullable(
  node: DocumentNode,
  nullable: boolean,
): DocumentNode {
  const branches = node.anyOf ?? [];
  const nonNullBranches = branches.filter(
    (branch) => branch.type !== "null" || branch.ref,
  );

  if (nullable) {
    if (nonNullBranches.length !== branches.length) return node;
    return { ...node, anyOf: [...branches, createNode("null")] };
  }

  if (nonNullBranches.length === branches.length) return node;
  if (nonNullBranches.length !== 1) {
    return { ...node, anyOf: nonNullBranches };
  }

  return mergeNullableWrapperIntoBranch(node, nonNullBranches[0]);
}

function wrapNodeInNullableAnyOf(node: DocumentNode): DocumentNode {
  return {
    id: node.id,
    title: node.title,
    description: node.description,
    rest: node.rest,
    order: node.order,
    anyOf: [cloneNodeAsAnyOfBranch(node), createNode("null")],
  };
}

function cloneNodeAsAnyOfBranch(node: DocumentNode): DocumentNode {
  return {
    ...node,
    id: createId(),
    type: nonNullType(node.type),
    title: undefined,
    description: undefined,
    rest: {},
    order: undefined,
  };
}

function nonNullType(type: DocumentNode["type"]): DocumentNode["type"] {
  if (!Array.isArray(type)) return type;
  const types = type.filter((entry) => entry !== "null");
  if (types.length === 0) return undefined;
  return types.length === 1 ? types[0] : types;
}

function mergeNullableWrapperIntoBranch(
  wrapper: DocumentNode,
  branch: DocumentNode,
): DocumentNode {
  return {
    ...branch,
    id: wrapper.id,
    title: wrapper.title ?? branch.title,
    description: wrapper.description ?? branch.description,
    rest: { ...branch.rest, ...wrapper.rest },
    order: wrapper.order ?? branch.order,
  };
}

export function createNode(
  type: JSONSchema7TypeName | "enum" = "string",
): DocumentNode {
  return normalizeNodeForType({ id: createId(), rest: {} }, type);
}

export function createEnumValue(): EnumValue {
  return { id: createId("enum"), value: "" };
}

export function updateEffectiveNodeShape(
  node: DocumentNode,
  fn: (node: DocumentNode) => DocumentNode,
): DocumentNode {
  if (node.anyOf) {
    return {
      ...node,
      anyOf: mapPreserve(node.anyOf, (branch) =>
        branch.type === "null" && !branch.ref ? branch : fn(branch),
      ),
    };
  }
  return fn(node);
}

import type { JSONSchema7TypeName } from "json-schema";

/**
 * Stable, intrinsic node identity.
 *
 * Born when a node is created, stable across renames / reorders / retypes, dies
 * with the node. NEVER derived from a mutable key or a positional path — that is
 * the whole reason this Document model exists instead of editing JSON Schema in
 * place.
 */
export type NodeId = string;
export type PropertyId = string;

/** A JSON Schema literal (enum entries, const, default, …). */
export type JsonValue =
  | string
  | number
  | boolean
  | null
  | JsonValue[]
  | { [key: string]: JsonValue };

/**
 * The editor's source of truth: a Document — a total, identity-bearing,
 * order-explicit representation of a JSON Schema.
 *
 * Design contract (see ./DESIGN.md):
 *
 *  1. Identity is intrinsic. Every node carries an `id` field; we never key a
 *     node by its property name or its path.
 *
 *  2. Order is explicit. Children JSON Schema keys by name (`properties`, `$defs`)
 *     are stored as ORDERED arrays of entries, so reordering is `arrayMove` and
 *     never depends on JS object key-order.
 *
 *  3. Losslessness by construction. Every keyword we don't model structurally is
 *     carried verbatim in `rest` and projected straight back out. Editing a node
 *     spreads it (`{ ...node, description }`), so unknown keywords ride along.
 *
 *  4. References are by id, not by name. A `$ref` resolves to a Definition's
 *     `id` on import, so renaming a definition can never break a reference; the
 *     `#/$defs/Name` pointer is re-projected from the def's current name on export.
 *
 *  5. The Document can hold transient-invalid states (empty/duplicate keys while
 *     typing). Cleanup (dropping empty keys, etc.) happens at the EXPORT boundary,
 *     never in the model — which is what lets the component be fully controlled.
 */
export interface DocumentNode {
  id: NodeId;

  /**
   * Mirrors JSON Schema `type`. A single name is the common case; an array
   * encodes a type-union such as `["string", "null"]` (nullable). Absent = "any".
   */
  type?: JSONSchema7TypeName | JSONSchema7TypeName[];

  title?: string;
  description?: string;

  /** object: ordered, identity-bearing property entries. */
  properties?: PropertyEntry[];

  /** Required names from the source that are not modeled as property entries. */
  extraRequired?: string[];

  /** Source order for `required[]`, used to preserve external required names. */
  requiredOrder?: string[];

  /** array: the item schema. (Tuple `items` arrays are carried in `rest` for v1.) */
  items?: DocumentNode;

  /** enum: ordered, identity-bearing values. Base type comes from `type`. */
  enum?: EnumValue[];

  /** $ref: id of the Definition this node points at, resolved on import. */
  ref?: NodeId;

  /** Composition keywords, recursively modeled. */
  anyOf?: DocumentNode[];
  oneOf?: DocumentNode[];
  allOf?: DocumentNode[];

  /**
   * Every keyword we don't model structurally — `const`, `default`, `format`,
   * `pattern`, `minLength`, `examples`, `additionalProperties`, `x-*`, … — kept
   * verbatim and projected straight back out. This is what makes the round-trip
   * lossless.
   */
  rest: Record<string, unknown>;

  /**
   * Internal: source key order, replayed on export for byte-faithful round-trips.
   * Kept off `rest` so a real keyword named `__order` can't collide with it.
   */
  order?: string[];

  /**
   * Internal: a boolean schema (`true` / `false`) has no structure to model; its
   * literal value is carried here.
   */
  booleanSchema?: boolean;
}

/**
 * A named child of an object. The `key` is mutable and freely editable; the
 * `required` flag lives on the parent/child EDGE here (in JSON Schema it lives in
 * the parent's `required[]` array, which we distribute onto entries on import and
 * rebuild on export).
 */
export interface PropertyEntry {
  id: PropertyId;
  key: string;
  /** Empty key created by the editor while typing; omitted from projection. */
  isTransient?: boolean;
  required: boolean;
  node: DocumentNode;
}

/** A single enum option. `id` keeps the row stable while its value is edited. */
export interface EnumValue {
  id: NodeId;
  value: JsonValue;
}

/** A named definition under `$defs`. `name` is mutable; references point at `id`. */
export interface DefinitionEntry {
  id: NodeId;
  name: string;
  node: DocumentNode;
}

/** The whole editor document — the single source of truth held in one useState. */
export interface SchemaDocument {
  root: DocumentNode;
  /** Named definitions ($defs / legacy definitions), ordered. */
  defs: DefinitionEntry[];
  /**
   * Document-level round-trip metadata we don't surface structurally — which defs
   * keyword the source used, top-level `$schema`/`$id`, etc. Carried verbatim.
   */
  rest: Record<string, unknown>;
}

/**
 * The effective "kind" of a node for the UI. Derived (see ./derive.ts), never
 * stored — there is exactly one source of truth and this is a projection of it.
 */
export type SchemaKind =
  | JSONSchema7TypeName // string | number | integer | boolean | object | array | null
  | "enum"
  | "ref"
  | "union"
  | "any";

import type { JSONSchema7Definition } from "json-schema";

import { projectNode } from "@/components/schema-editor/document/convert";
import {
  getEffectiveKind,
  isNullable,
  resolveRef,
} from "@/components/schema-editor/document/derive";
import type { SchemaEditorType } from "@/components/schema-editor/document/type-operations";
import type {
  DocumentNode,
  EnumValue,
  PropertyEntry,
  SchemaDocument,
} from "@/components/schema-editor/document/types";

export interface DocumentDefinitionView {
  definitionId: string;
  definitionName: string;
  schema: JSONSchema7Definition;
}

export interface DocumentPropertyView {
  propertyId: string;
  propertyName: string;
  isRequired: boolean;
  nodeView: DocumentNodeView;
}

export interface DocumentNodeView {
  nodeId: string;
  docNode: DocumentNode;
  effectiveNode: DocumentNode;
  type: SchemaEditorType | "$ref" | "any" | "union" | "null";
  title?: string;
  description?: string;
  refName?: string;
  isNullable: boolean;
  properties: DocumentPropertyView[];
  items?: DocumentNodeView;
  enumEntries: EnumValue[];
}

export interface SchemaDocumentView {
  root: DocumentNodeView;
  definitions: DocumentDefinitionView[];
}

export function getSchemaDocumentView(doc: SchemaDocument): SchemaDocumentView {
  return {
    root: getDocumentNodeView(doc, doc.root),
    definitions: doc.defs.map((definition) => ({
      definitionId: definition.id,
      definitionName: definition.name,
      schema: projectNode(doc, definition.node),
    })),
  };
}

export function getDocumentNodeView(
  doc: SchemaDocument,
  node: DocumentNode,
): DocumentNodeView {
  const effectiveNode = getViewEffectiveNode(node);
  return {
    nodeId: node.id,
    docNode: node,
    effectiveNode,
    type: getDocumentEditorType(doc, effectiveNode),
    title: node.title,
    description: node.description,
    refName: resolveRef(doc, effectiveNode)?.name,
    isNullable: isNullable(node),
    properties: (effectiveNode.properties ?? []).map((property) =>
      getDocumentPropertyView(doc, property),
    ),
    items: effectiveNode.items
      ? getDocumentNodeView(doc, effectiveNode.items)
      : undefined,
    enumEntries: effectiveNode.enum ?? [],
  };
}

function getDocumentPropertyView(
  doc: SchemaDocument,
  property: PropertyEntry,
): DocumentPropertyView {
  return {
    propertyId: property.id,
    propertyName: property.key,
    isRequired: property.required,
    nodeView: getDocumentNodeView(doc, property.node),
  };
}

function getViewEffectiveNode(node: DocumentNode): DocumentNode {
  if (node.anyOf) {
    return (
      node.anyOf.find((branch) => branch.type !== "null" || branch.ref) ?? node
    );
  }
  return node;
}

function getDocumentEditorType(
  doc: SchemaDocument,
  node: DocumentNode,
): DocumentNodeView["type"] {
  if (node.ref) return "$ref";
  if (node.enum) return "enum";

  const kind = getEffectiveKind(node);
  if (kind === "ref") return "$ref";
  if (kind !== "string") return kind;

  const format = node.rest.format;
  if (format === "date") return "date";
  if (format === "time") return "time";
  if (format === "date-time") return "datetime";

  return resolveRef(doc, node) ? "$ref" : "string";
}

import type { JSONSchema7Definition } from "json-schema";

import type { ExtendedJSONSchema7 } from "@/components/schema-editor/lib/json-schema-types";
import { getEffectiveNode } from "@/components/schema-editor/lib/json-schema-utils";

import { formatTitle } from "../schema-title";

export function getEffectiveType(node: ExtendedJSONSchema7): {
  type: string;
  isNullable: boolean;
} {
  if (node.anyOf && Array.isArray(node.anyOf)) {
    const nonNull = node.anyOf.find(
      (branch: JSONSchema7Definition) =>
        typeof branch === "object" &&
        (branch.type !== "null" || branch.$ref || branch.enum),
    );
    const isNullable = node.anyOf.some(
      (branch: JSONSchema7Definition) =>
        typeof branch === "object" && branch.type === "null",
    );
    if (nonNull && typeof nonNull === "object") {
      if (nonNull.$ref) return { type: "$ref", isNullable };
      if (nonNull.enum) return { type: "enum", isNullable };
      if (nonNull.type === "string" && nonNull.format === "date") {
        return { type: "date", isNullable };
      }
      if (nonNull.type === "string" && nonNull.format === "time") {
        return { type: "time", isNullable };
      }
      if (nonNull.type === "string" && nonNull.format === "date-time") {
        return { type: "datetime", isNullable };
      }
      return { type: nonNull.type?.toString() || "string", isNullable };
    }
    return { type: "string", isNullable };
  }
  // A nullable scalar can also be encoded as a type union `["string", "null"]`
  // (the standard JSON Schema form, and what the document-model builder emits).
  // Treat that `null` member as nullability, not as part of the type name.
  const isTypeArrayNullable =
    Array.isArray(node.type) && node.type.includes("null");
  const effectiveTypeName = isTypeArrayNullable
    ? (node.type as string[]).find((member) => member !== "null")
    : node.type;

  if (node.enum) return { type: "enum", isNullable: isTypeArrayNullable };
  if (node.$ref) return { type: "$ref", isNullable: isTypeArrayNullable };
  if (effectiveTypeName === "string" && node.format === "date") {
    return { type: "date", isNullable: isTypeArrayNullable };
  }
  if (effectiveTypeName === "string" && node.format === "time") {
    return { type: "time", isNullable: isTypeArrayNullable };
  }
  if (effectiveTypeName === "string" && node.format === "date-time") {
    return { type: "datetime", isNullable: isTypeArrayNullable };
  }
  return {
    type: effectiveTypeName?.toString() || "string",
    isNullable: isTypeArrayNullable,
  };
}

export function defaultSchemaForType(type: string): ExtendedJSONSchema7 {
  switch (type) {
    case "string":
      return { type: "string" };
    case "number":
      return { type: "number" };
    case "integer":
      return { type: "integer" };
    case "boolean":
      return { type: "boolean" };
    case "object":
      return { type: "object", properties: {}, required: [] };
    case "array":
      return { type: "array", items: { type: "string" } };
    case "$ref":
      return {} as ExtendedJSONSchema7;
    case "enum":
      return { enum: [], type: "string" };
    case "date":
      return { type: "string", format: "date" };
    case "time":
      return { type: "string", format: "time" };
    case "datetime":
      return { type: "string", format: "date-time" };
    default:
      return { type: "string" };
  }
}

export function updateType(
  newType: string,
  nullable: boolean,
  oldNode: ExtendedJSONSchema7,
): ExtendedJSONSchema7 {
  const effectiveOldNode = getEffectiveNode(oldNode);
  const metadata: Partial<ExtendedJSONSchema7> = {};
  if (oldNode.title) metadata.title = oldNode.title;
  if (oldNode.description) metadata.description = oldNode.description;

  let baseSchema = defaultSchemaForType(newType);

  if (newType === "array") {
    baseSchema = {
      type: "array",
      items:
        effectiveOldNode.type === "object"
          ? effectiveOldNode
          : { type: "string" },
    };
  } else if (newType === "enum") {
    baseSchema = {
      type: "string",
      enum: effectiveOldNode.enum || [],
    };
  }

  if (nullable) {
    return {
      anyOf: [baseSchema, { type: "null" }],
      ...metadata,
    } as ExtendedJSONSchema7;
  }

  return { ...baseSchema, ...metadata };
}

export function setNullable(
  node: ExtendedJSONSchema7,
  nullable: boolean,
): ExtendedJSONSchema7 {
  const { title, description, ...rest } = node;

  if (nullable) {
    if (node.anyOf && Array.isArray(node.anyOf)) {
      const nonNullBranch = node.anyOf.find(
        (branch: JSONSchema7Definition) =>
          typeof branch === "object" && (branch.type !== "null" || branch.$ref),
      );
      const nonNullObject =
        typeof nonNullBranch === "object" ? nonNullBranch : {};

      return {
        anyOf: [{ ...nonNullObject }, { type: "null" }],
        ...(title ? { title } : {}),
        ...(description ? { description } : {}),
      };
    }

    // Strip any pre-existing `null` from a type union so the wrapped branch
    // isn't doubly-nullable (e.g. `["string","null"]` -> `"string"`).
    return {
      anyOf: [stripNullType({ ...rest }), { type: "null" }],
      ...(title ? { title } : {}),
      ...(description ? { description } : {}),
    };
  }

  if (node.anyOf && Array.isArray(node.anyOf)) {
    const nonNullBranch = node.anyOf.find(
      (branch: JSONSchema7Definition) =>
        typeof branch === "object" && (branch.type !== "null" || branch.$ref),
    );
    const nonNullObject =
      typeof nonNullBranch === "object" ? nonNullBranch : {};

    return {
      ...nonNullObject,
      ...(title ? { title } : {}),
      ...(description ? { description } : {}),
    };
  }

  // Plain node: also handle the type-union nullable form `["string","null"]`,
  // which carries no `anyOf` — drop the `null` member to make it non-nullable.
  return stripNullType(node);
}

/** Remove a `null` member from a `type` union, collapsing to a single name. */
function stripNullType(node: ExtendedJSONSchema7): ExtendedJSONSchema7 {
  if (!Array.isArray(node.type)) return node;
  const nonNull = node.type.filter((member) => member !== "null");
  return {
    ...node,
    type: (nonNull.length === 0
      ? undefined
      : nonNull.length === 1
        ? nonNull[0]
        : nonNull) as ExtendedJSONSchema7["type"],
  };
}

export function updateEffectiveNode(
  node: ExtendedJSONSchema7,
  updatedEffectiveNode: ExtendedJSONSchema7,
): ExtendedJSONSchema7 {
  if (node.anyOf && Array.isArray(node.anyOf)) {
    const anyOf = node.anyOf.map((branch: JSONSchema7Definition) =>
      typeof branch === "object" && branch.type === "null"
        ? branch
        : updatedEffectiveNode,
    );
    return { ...node, anyOf };
  }
  return updatedEffectiveNode;
}

export function updateSchemaProperty(
  schemaNode: ExtendedJSONSchema7,
  propertyKey: string,
  newPropertyName: string,
  updatedProperty: ExtendedJSONSchema7,
): ExtendedJSONSchema7 {
  // Refuse to rename onto an existing sibling: merging would drop the renamed
  // property's schema and leave a duplicate in `required`. Callers validate
  // name collisions upstream, so this is a defensive no-op.
  if (
    newPropertyName !== propertyKey &&
    schemaNode.properties &&
    Object.prototype.hasOwnProperty.call(schemaNode.properties, newPropertyName)
  ) {
    return schemaNode;
  }

  const effectiveNode = getEffectiveNode(updatedProperty);
  const cleanProperty = {
    ...effectiveNode,
    title: formatTitle(newPropertyName),
    ...(Array.isArray(effectiveNode.enum) && { type: "string" }),
  } as ExtendedJSONSchema7;
  const finalProperty = updateEffectiveNode(updatedProperty, cleanProperty);

  const oldProperties = schemaNode.properties || {};
  const newProperties: Record<string, ExtendedJSONSchema7> = {};
  let found = false;

  Object.keys(oldProperties).forEach((key) => {
    if (key === propertyKey && newPropertyName !== propertyKey) {
      setRecordValue(newProperties, newPropertyName, finalProperty);
      found = true;
    } else if (isJSONSchema(oldProperties[key])) {
      setRecordValue(
        newProperties,
        key,
        oldProperties[key] as ExtendedJSONSchema7,
      );
    }
  });

  if (!found && newPropertyName !== propertyKey) {
    setRecordValue(newProperties, newPropertyName, finalProperty);
    delete newProperties[propertyKey];
  }

  if (newPropertyName !== propertyKey) {
    const required = Array.isArray(schemaNode.required)
      ? schemaNode.required.map((key: string) =>
          key === propertyKey ? newPropertyName : key,
        )
      : [];

    return {
      ...schemaNode,
      properties: newProperties,
      required,
    };
  }

  return {
    ...schemaNode,
    properties: {
      ...newProperties,
      [propertyKey]: finalProperty,
    },
  };
}

function isJSONSchema(
  value: JSONSchema7Definition,
): value is ExtendedJSONSchema7 {
  return typeof value === "object" && value !== null;
}

function setRecordValue<T>(record: Record<string, T>, key: string, value: T) {
  Object.defineProperty(record, key, {
    value,
    enumerable: true,
    configurable: true,
    writable: true,
  });
}

import * as React from "react";
import { useState } from "react";
import { PlusIcon, X } from "lucide-react";

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

interface EnumCreationDialogProps {
  isOpen: boolean;
  onClose: () => void;
  onConfirm: (enumValues: string[]) => void;
  onCancel: () => void;
}

interface EnumCreationDialogContentProps {
  onClose: () => void;
  onConfirm: (enumValues: string[]) => void;
  onCancel: () => void;
}

function EnumCreationDialogContent({
  onClose,
  onConfirm,
  onCancel,
}: EnumCreationDialogContentProps) {
  const [enumValues, setEnumValues] = useState<string[]>([]); // Start with no values
  const [newValue, setNewValue] = useState("");
  const enumInputRefs = React.useRef<Array<HTMLInputElement | null>>([]);
  const pendingFocusIndexRef = React.useRef<number | null>(null);

  const setEnumInputRef = React.useCallback(
    (index: number, input: HTMLInputElement | null) => {
      enumInputRefs.current[index] = input;
      if (input && pendingFocusIndexRef.current === index) {
        pendingFocusIndexRef.current = null;
        input.focus();
      }
    },
    [],
  );

  const handleAddValue = () => {
    if (newValue.trim()) {
      setEnumValues((prev) => [...prev, newValue.trim()]);
      setNewValue("");
    }
  };

  const handleAddFromEmpty = () => {
    pendingFocusIndexRef.current = enumValues.length;
    setEnumValues((prev) => [...prev, ""]);
  };

  const handleRemoveValue = (index: number) => {
    setEnumValues((prev) => prev.filter((_, i) => i !== index));
  };

  const handleEditValue = (index: number, value: string) => {
    setEnumValues((prev) => prev.map((val, i) => (i === index ? value : val)));
  };

  const handleConfirm = () => {
    // Filter out empty values
    const validValues = enumValues.filter((val) => val.trim() !== "");
    if (validValues.length > 0) {
      onConfirm(validValues);
      onClose();
    }
  };

  const handleCancel = () => {
    onCancel();
    onClose();
  };

  const validValuesCount = enumValues.filter((val) => val.trim() !== "").length;

  return (
    <DialogContent className="max-h-[85vh] overflow-y-auto sm:max-w-lg">
      <DialogHeader>
        <DialogTitle>Update Field</DialogTitle>
        <DialogDescription>
          Define the allowed values for this field.
        </DialogDescription>
      </DialogHeader>

      <div className="space-y-4">
        <div>
          <Label className="mb-2">Enabled Options</Label>

          {enumValues.length > 0 && (
            <div className="mb-4 space-y-2">
              {enumValues.map((value, index) => (
                <div key={index} className="flex items-center gap-2">
                  <Input
                    value={value}
                    ref={(input) => {
                      setEnumInputRef(index, input);
                    }}
                    onChange={(e) => handleEditValue(index, e.target.value)}
                    onKeyDown={(e) => {
                      if (e.key === "Enter" && value.trim()) {
                        if (index === enumValues.length - 1) {
                          handleAddFromEmpty();
                        } else {
                          enumInputRefs.current[index + 1]?.focus();
                        }
                      }
                    }}
                    className="flex-1"
                    placeholder={`Value ${index + 1}`}
                  />
                  <Button
                    type="button"
                    variant="ghost"
                    size="sm"
                    className="h-8 w-8 p-1"
                    onClick={() => handleRemoveValue(index)}
                    disabled={enumValues.length === 1}
                  >
                    <X className="h-4 w-4" />
                  </Button>
                </div>
              ))}
            </div>
          )}

          <div className="flex items-center gap-2">
            <Input
              value={newValue}
              onChange={(e) => setNewValue(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === "Enter" && newValue.trim()) {
                  handleAddValue();
                }
              }}
              className="flex-1"
              placeholder="Add another value"
            />
            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={handleAddValue}
              disabled={!newValue.trim()}
            >
              <PlusIcon className="mr-1 h-4 w-4" />
              Add
            </Button>
          </div>

          <p className="text-muted-foreground mt-2 text-xs">
            {validValuesCount} value{validValuesCount !== 1 ? "s" : ""} defined.
          </p>
        </div>
      </div>

      <DialogFooter>
        <Button type="button" variant="outline" onClick={handleCancel}>
          Cancel
        </Button>
        <Button
          type="button"
          variant="default"
          onClick={handleConfirm}
          disabled={validValuesCount === 0}
        >
          Update Field ({validValuesCount} value
          {validValuesCount !== 1 ? "s" : ""})
        </Button>
      </DialogFooter>
    </DialogContent>
  );
}

export function EnumCreationDialog({
  isOpen,
  onClose,
  onConfirm,
  onCancel,
}: EnumCreationDialogProps) {
  const handleOpenChange = (open: boolean) => {
    if (!open) {
      onCancel();
      onClose();
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={handleOpenChange}>
      {isOpen ? (
        <EnumCreationDialogContent
          key="enum-creation-dialog"
          onClose={onClose}
          onConfirm={onConfirm}
          onCancel={onCancel}
        />
      ) : null}
    </Dialog>
  );
}

