import type { JSONSchema7 } from "json-schema";

/**
 * The schema editor works with standard JSON Schema (Draft 7). This is a plain
 * alias for `JSONSchema7` — no custom extensions — kept under a single shared
 * name so the editor's many imports stay stable.
 */
export type ExtendedJSONSchema7 = JSONSchema7;

import type { JSONSchema7Definition } from "json-schema";
import type { ExtendedJSONSchema7 } from "@/components/schema-editor/lib/json-schema-types";

// Pydantic reserved names that actually break model creation
const PYDANTIC_RESERVED = [
  "__root__",
  "model_config",
  "model_post_init",
  "model_validate",
  "model_dump",
];

// Generic name validator for Pydantic compatible field and definition names
export function validateName(
  name: string,
  existingNames: string[] = [],
  currentName?: string,
  entityType: string = "name",
): string | null {
  if (!/^[a-zA-Z_][a-zA-Z0-9_]{0,63}$/.test(name)) {
    return "Name must start with a letter or underscore, contain only letters, numbers, or underscores, and be at most 64 characters long";
  }

  if (PYDANTIC_RESERVED.includes(name)) {
    return `"${name}" is a Pydantic reserved name`;
  }

  const namesToCheck = currentName
    ? existingNames.filter((n) => n.toLowerCase() !== currentName.toLowerCase())
    : existingNames;

  if (namesToCheck.some((n) => n.toLowerCase() === name.toLowerCase())) {
    return `A ${entityType} with the name "${name}" already exists (names are case-insensitive)`;
  }

  return null;
}

/**
 * Unwrap a nullable `anyOf` node (e.g. `{ anyOf: [<schema>, { type: "null" }] }`)
 * down to its underlying non-null schema so it can be inspected directly.
 */
export function getEffectiveNode(
  node: ExtendedJSONSchema7,
): ExtendedJSONSchema7 {
  if (node.anyOf && Array.isArray(node.anyOf)) {
    const nonNull = node.anyOf.find(
      (b: JSONSchema7Definition) =>
        typeof b === "object" && (b.type !== "null" || b.$ref),
    );
    return nonNull && typeof nonNull === "object" ? nonNull : node;
  }
  return node;
}

import * as React from "react";

import type { ExtendedJSONSchema7 } from "@/components/schema-editor/lib/json-schema-types";
import { PropertyForm } from "@/components/schema-editor/property-form/property-form";
import type {
  PropertyDraft,
  PropertyFormMode,
  PropertyFormSchemaContext,
} from "@/components/schema-editor/property-form/types";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";

interface NodeDialogProps {
  isOpen: boolean;
  onClose: () => void;
  onChange: (newNode: ExtendedJSONSchema7) => void;
  onNameChange?: (newName: string, updatedNode?: ExtendedJSONSchema7) => void;
  onDelete?: () => void;
  node: ExtendedJSONSchema7;
  name: string;
  mode: PropertyFormMode;
  siblingNames: string[];
  formContext: Omit<PropertyFormSchemaContext, "siblingNames" | "originalName">;
}

export function NodeDialog({
  isOpen,
  onClose,
  onChange,
  onNameChange,
  onDelete,
  node,
  name,
  mode,
  siblingNames,
  formContext,
}: NodeDialogProps) {
  const handleCommit = async (next: PropertyDraft) => {
    if (next.name !== name && onNameChange) {
      onNameChange(next.name, next.schemaNode);
    } else {
      onChange(next.schemaNode);
    }

    onClose();
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="max-h-[90vh] gap-2 overflow-y-auto p-0 sm:max-w-xl">
        <DialogHeader className="px-4 pt-4">
          <DialogTitle>
            {mode === "readOnly" ? "View Property" : "Edit Property"}
          </DialogTitle>
          <DialogDescription>
            {mode === "readOnly"
              ? "View property name, type, description, and other characteristics."
              : "Modify property name, type, description, and other characteristics."}
          </DialogDescription>
        </DialogHeader>

        <PropertyForm
          propertyDraft={{ name, schemaNode: node }}
          schemaContext={{
            ...formContext,
            siblingNames,
            originalName: name,
          }}
          onCommitPropertyDraft={handleCommit}
          onCancel={onClose}
          onDelete={onDelete}
          submitLabel="Save"
          mode={mode}
        />
      </DialogContent>
    </Dialog>
  );
}

"use client";

import * as React from "react";

import type { SchemaTypeMenuTrailingContent } from "@/components/schema-editor/primitives/schema-type-menu";

const LazyObjectTemplateSubmenu = React.lazy(() =>
  import(
    "@/components/schema-editor/optional/object-templates/object-template-menu"
  ).then((module) => ({
    default: module.ObjectTemplateSubmenu,
  })),
);

export function createObjectTemplateTypeTrailingContent({
  onSelectTemplate,
}: {
  onSelectTemplate: (templateName: string) => void;
}): SchemaTypeMenuTrailingContent {
  function ObjectTemplateTypeTrailingContent({
    editable,
  }: {
    editable: boolean;
  }) {
    return (
      <React.Suspense fallback={null}>
        <LazyObjectTemplateSubmenu
          onSelectTemplate={(templateName) => {
            if (!editable) return;
            onSelectTemplate(templateName);
          }}
        />
      </React.Suspense>
    );
  }

  ObjectTemplateTypeTrailingContent.displayName =
    "ObjectTemplateTypeTrailingContent";
  return ObjectTemplateTypeTrailingContent;
}

"use client";

import { CloudUpload, Copy, Download } from "lucide-react";
import { toast } from "sonner";

import type { ExtendedJSONSchema7 } from "@/components/schema-editor/lib/json-schema-types";
import { DropdownMenuItem } from "@/components/ui/dropdown-menu";

export function ImportExportMenuItems({
  node,
  onReplaceRoot,
}: {
  node: ExtendedJSONSchema7;
  onReplaceRoot: (node: ExtendedJSONSchema7) => void;
}) {
  const handleDownloadSchema = () => {
    try {
      const schemaBlob = new Blob([JSON.stringify(node, null, 2)], {
        type: "application/json",
      });
      const url = URL.createObjectURL(schemaBlob);
      const link = document.createElement("a");
      link.href = url;
      link.download = node.title
        ? `${node.title.toLowerCase().replace(/\s+/g, "-")}.json`
        : "schema.json";

      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);

      toast.success("Download Started", {
        description: "Your schema has been downloaded successfully.",
      });
    } catch (error) {
      console.error("Error downloading schema:", error);
      toast.error("Download Failed", {
        description: "There was an error downloading your schema.",
      });
    }
  };

  const handleUploadSchema = () => {
    try {
      const fileInput = document.createElement("input");
      fileInput.type = "file";
      fileInput.accept = ".json";
      fileInput.style.display = "none";

      fileInput.addEventListener("change", (event) => {
        const target = event.target as HTMLInputElement;
        if (target.files && target.files.length > 0) {
          const file = target.files[0];
          const reader = new FileReader();

          reader.onload = async (loadEvent) => {
            try {
              const content = loadEvent.target?.result as string;
              onReplaceRoot(JSON.parse(content));
              toast.success("Schema Uploaded", {
                description:
                  "Your schema has been uploaded and applied successfully.",
              });
            } catch (error) {
              console.error("Error parsing uploaded schema:", error);
              toast.error("Upload Failed", {
                description: "The uploaded file is not a valid JSON schema.",
              });
            }
          };

          reader.readAsText(file);
        }

        document.body.removeChild(fileInput);
      });

      document.body.appendChild(fileInput);
      fileInput.click();
    } catch (error) {
      console.error("Error uploading schema:", error);
      toast.error("Upload Failed", {
        description: "There was an error uploading your schema.",
      });
    }
  };

  const handleCopy = () => {
    try {
      const formattedSchema = JSON.stringify(node, null, 2);
      navigator.clipboard
        .writeText(formattedSchema)
        .then(() => {
          toast.success("Copied to Clipboard", {
            description: "Your schema has been copied to the clipboard.",
          });
        })
        .catch((error) => {
          console.error("Error copying to clipboard:", error);
          const textArea = document.createElement("textarea");
          textArea.value = formattedSchema;
          textArea.style.position = "fixed";
          textArea.style.left = "-999999px";
          textArea.style.top = "-999999px";
          document.body.appendChild(textArea);
          textArea.focus();
          textArea.select();

          try {
            document.execCommand("copy");
            textArea.remove();
            toast.success("Copied to Clipboard", {
              description: "Your schema has been copied to the clipboard.",
            });
          } catch (copyError) {
            console.error("Unable to copy schema", copyError);
            toast.error("Copy Failed", {
              description:
                "There was an error copying your schema to the clipboard.",
            });
            textArea.remove();
          }
        });
    } catch (error) {
      console.error("Error preparing schema for copy:", error);
      toast.error("Copy Failed", {
        description: "There was an error preparing your schema for copying.",
      });
    }
  };

  return (
    <>
      <DropdownMenuItem onClick={handleDownloadSchema}>
        <Download className="mr-2 h-4 w-4" />
        Download
      </DropdownMenuItem>
      <DropdownMenuItem onClick={handleUploadSchema}>
        <CloudUpload className="mr-2 h-4 w-4" />
        Upload
      </DropdownMenuItem>
      <DropdownMenuItem onClick={handleCopy}>
        <Copy className="mr-2 h-4 w-4" />
        Copy to clipboard
      </DropdownMenuItem>
    </>
  );
}

