import * as React from "react";
import type { JSONSchema7Type } from "json-schema";

export function useEnumValueIdentity({
  resetKey,
  values,
}: {
  resetKey: string;
  values: JSONSchema7Type[];
}) {
  const resetKeyRef = React.useRef(resetKey);
  const nextIdRef = React.useRef(0);
  const idsRef = React.useRef<string[]>([]);

  if (resetKeyRef.current !== resetKey) {
    resetKeyRef.current = resetKey;
    nextIdRef.current = 0;
    idsRef.current = [];
  }

  while (idsRef.current.length < values.length) {
    idsRef.current.push(createEnumValueId(nextIdRef.current));
    nextIdRef.current += 1;
  }

  if (idsRef.current.length > values.length) {
    idsRef.current.length = values.length;
  }

  return {
    ids: idsRef.current,
    removeId: (id: string) => {
      const index = idsRef.current.indexOf(id);
      if (index >= 0) {
        idsRef.current.splice(index, 1);
      }
    },
  };
}

function createEnumValueId(sequence: number) {
  return `enum-value-${sequence}`;
}

"use client";

import * as React from "react";
import type { JSONSchema7Type } from "json-schema";

import { Label } from "@/components/ui/label";
import { SchemaChipAddRow } from "@/components/schema-editor/primitives/schema-chip-add-row";
import { SchemaChipList } from "@/components/schema-editor/primitives/schema-chip-list";
import {
  formatEnumValueInput,
  parseEnumValueInput,
} from "@/components/schema-editor/property-form/model/enum-values";

import { useEnumValueIdentity } from "./enum-value-identity";

export function EnumValuesField({
  values,
  resetKey,
  disabled,
  onChange,
}: {
  values: JSONSchema7Type[];
  resetKey: string;
  disabled: boolean;
  onChange: (values: JSONSchema7Type[]) => void;
}) {
  const [nextValueState, setNextValueState] = React.useState({
    resetKey,
    value: "",
  });
  const nextValue =
    nextValueState.resetKey === resetKey ? nextValueState.value : "";
  const setNextValue = React.useCallback(
    (value: string) => setNextValueState({ resetKey, value }),
    [resetKey],
  );
  const valueIdentity = useEnumValueIdentity({ resetKey, values });

  const items = values.map((value, index) => {
    const inputValue = formatEnumValueInput(value);
    return {
      id: valueIdentity.ids[index],
      inputLabel: `Option ${index + 1}: ${inputValue || "empty"}`,
      removeLabel: `Remove option ${inputValue}`,
      value: inputValue,
    };
  });

  const indexFromId = (id: string) => valueIdentity.ids.indexOf(id);
  const addInput = {
    inputLabel: "Add new value",
    placeholder: "Add new value",
    submitLabel: "Add",
    value: nextValue,
    onChange: setNextValue,
    onSubmit: () => {
      onChange([...values, parseEnumValueInput(nextValue)]);
      setNextValueState({ resetKey, value: "" });
    },
  };

  return (
    <div className="space-y-2">
      <Label className="text-muted-foreground text-xs">Enabled options</Label>
      <SchemaChipList
        editable={!disabled}
        items={items}
        onRemove={(id) => {
          const index = indexFromId(id);
          valueIdentity.removeId(id);
          onChange(values.filter((_value, current) => current !== index));
        }}
        onReplace={(id, value) => {
          const index = indexFromId(id);
          const nextValues = values.slice();
          nextValues[index] = parseEnumValueInput(value);
          onChange(nextValues);
        }}
      />
