export function isObjectSchema(
  value: JSONSchema7Definition | undefined,
): value is ExtendedJSONSchema7 {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

export function setDraftNullable(
  propertyDraft: PropertyDraft,
  isNullable: boolean,
): PropertyDraft {
  return {
    ...propertyDraft,
    schemaNode: setNullable(propertyDraft.schemaNode, isNullable),
  };
}

export function getArrayItemsForDraft(
  schemaNode: ExtendedJSONSchema7,
): ExtendedJSONSchema7 {
  const effectiveSchemaNode = getEffectiveNode(schemaNode);
  const effectiveItems = Array.isArray(effectiveSchemaNode.items)
    ? undefined
    : effectiveSchemaNode.items;
  return isObjectSchema(effectiveItems) ? effectiveItems : { type: "string" };
}

import type { JSONSchema7Type } from "json-schema";

export function formatEnumValueInput(value: JSONSchema7Type): string {
  return typeof value === "string" ? value : JSON.stringify(value);
}

export function parseEnumValueInput(value: string): JSONSchema7Type {
  const trimmedValue = value.trim();
  if (!trimmedValue) return "";

  try {
    const parsedValue = JSON.parse(trimmedValue);
    if (isJsonSchemaValue(parsedValue)) return parsedValue;
  } catch {
    return trimmedValue;
  }

  return trimmedValue;
}

function isJsonSchemaValue(value: unknown): value is JSONSchema7Type {
  if (value === null) return true;
  if (
    typeof value === "string" ||
    typeof value === "number" ||
    typeof value === "boolean"
  ) {
    return true;
  }
  if (Array.isArray(value)) return value.every(isJsonSchemaValue);
  if (typeof value !== "object") return false;

  return Object.values(value).every(isJsonSchemaValue);
}

