  getTypeIcon,
} from "@/components/schema-editor/type-icons";

export function createTypeMenuValue({
  type,
  refName,
}: {
  type: string;
  refName?: string;
}): SchemaTypeMenuValue {
  return {
    id: type,
    label: schemaTypeLabel(type, refName),
    icon: schemaTypeIcon(type, refName),
  };
}

export function createPrimitiveTypeItems({
  onSelectType,
}: {
  onSelectType: (type: SchemaTypeOptionId) => void;
}): SchemaTypeMenuItem[] {
  return schemaTypeOptions.map((option) => ({
    id: option.id,
    label: option.label,
    icon: option.icon,
    onSelect: () => onSelectType(option.id),
  }));
}

export function createDefinitionTypeSubmenu({
  createDefinitionLabel,
  definitionNames,
  onCreateDefinition,
  onSelectDefinition,
}: {
  createDefinitionLabel: string;
  definitionNames: string[];
  onCreateDefinition: () => void;
  onSelectDefinition: (definitionName: string) => void;
}): SchemaTypeMenuSection {
  return {
    id: "definitions",
    kind: "submenu",
    label: "definition",
    icon: getTypeIcon("$ref"),
    items:
      definitionNames.length === 0
        ? [
            {
              id: "create-definition",
              label: createDefinitionLabel,
              icon: <PlusIcon className="h-4 w-4" />,
              onSelect: onCreateDefinition,
            },
          ]
        : definitionNames.map((definitionName) => ({
            id: definitionName,
            label: definitionName,
            icon: getTemplateIcon(definitionName),
            onSelect: () => onSelectDefinition(definitionName),
          })),
  };
}

"use client";

import Ajv from "ajv";
import type { ErrorObject, ValidateFunction } from "ajv";
import draft7MetaSchema from "ajv/dist/refs/json-schema-draft-07.json";

import {
  addJsonSchemaErrors,
  addJsonSchemaFormats,
} from "@/components/schema-editor/lib/configure-ajv";

let ajvSingleton: Ajv | null = null;
let validateJsonSchemaSingleton: ValidateFunction | null = null;

function isMutableObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function injectConstraints(schema: unknown): void {
  if (!isMutableObject(schema)) return;

  if (schema.type === "object") {
    schema.propertyNames = {
      type: "string",
      pattern: "^(?![-+]?(\\d+(\\.\\d*)?|\\.\\d+)$).+",
    };
  }

  for (const value of Object.values(schema)) {
    if (isMutableObject(value)) {
      injectConstraints(value);
    }
  }
}

function buildEnrichedDraft7MetaSchema(): Record<string, unknown> {
  const schema = structuredClone(draft7MetaSchema) as Record<string, unknown>;
  schema.$id = "http://retab-json-schema.org/draft-07/enriched-schema#";
  injectConstraints(schema);

  if (!isMutableObject(schema.properties)) {
    schema.properties = {};
  }

  const properties = schema.properties;
  if (!isMutableObject(properties)) return schema;

  properties.additionalProperties = {
    const: false,
  };

  return schema;
}

function getAjv(): Ajv {
  if (!ajvSingleton) {
    ajvSingleton = new Ajv({
      allErrors: true,
      allowUnionTypes: true,
    });
    addJsonSchemaFormats(ajvSingleton);
    addJsonSchemaErrors(ajvSingleton);
  }

  return ajvSingleton;
}

function getValidator(): ValidateFunction {
  if (!validateJsonSchemaSingleton) {
    validateJsonSchemaSingleton = getAjv().compile(
      buildEnrichedDraft7MetaSchema(),
    );
  }

  return validateJsonSchemaSingleton;
}

export function validateJsonSchema(schema: unknown): boolean {
  return !!getValidator()(schema);
}

export function getJsonSchemaValidationErrors(): ErrorObject[] | null {
  return getValidator().errors ?? null;
}

export function errorsText(
  errors?: ErrorObject[] | null,
  options?: { separator?: string; dataVar?: string },
): string {
  return getAjv().errorsText(errors ?? undefined, options);
}

import * as React from "react";

import type { ExtendedJSONSchema7 } from "@/components/schema-editor/lib/json-schema-types";
import type { SchemaEditorMode } from "@/components/schema-editor/schema-editor-mode";

export type TopLevelEditorProps = {
  node: ExtendedJSONSchema7;
  mode: SchemaEditorMode;
  showImportExportActions?: boolean;
  onTitleChange: (title: string) => void;
  onDescriptionChange: (description: string) => void;
  onEraseAll: () => void;
  onEraseDescriptions: () => void;
  onReplaceRoot: (node: ExtendedJSONSchema7) => void;
};

export type TopLevelConfirmAction = "eraseAll" | "eraseDescriptions";

export function buildTopLevelMetadataValues(node: ExtendedJSONSchema7) {
  return {
    title: node.title || "",
    description: node.description || "",
  };
}

export function useTopLevelEditorController({
  node,
  onTitleChange,
  onDescriptionChange,
  onEraseAll,
  onEraseDescriptions,
}: Pick<
  TopLevelEditorProps,
  | "node"
  | "onTitleChange"
  | "onDescriptionChange"
  | "onEraseAll"
  | "onEraseDescriptions"
>) {
  const [metadataDialogOpen, setMetadataDialogOpen] = React.useState(false);
  const [confirmAction, setConfirmAction] =
    React.useState<TopLevelConfirmAction | null>(null);
  const [metadataValues, setMetadataValues] = React.useState(() =>
    buildTopLevelMetadataValues(node),
  );
  const [draftTitle, setDraftTitle] = React.useState(node.title || "");
  const [isTitleDirty, setIsTitleDirty] = React.useState(false);
  const [draftDescription, setDraftDescription] = React.useState(
    node.description || "",
  );
  const [isDescriptionDirty, setIsDescriptionDirty] = React.useState(false);
  const [dialogPropertyName, setDialogPropertyName] = React.useState(
    node.title || "",
  );

  const currentTitle = isTitleDirty ? draftTitle : node.title || "";
  const currentDescription = isDescriptionDirty
    ? draftDescription
    : node.description || "";

  const commitTitle = React.useCallback(() => {
    if (currentTitle !== (node.title || "")) {
      onTitleChange(currentTitle || "");
    }
    setIsTitleDirty(false);
    setDraftTitle(node.title || "");
  }, [currentTitle, node.title, onTitleChange]);

  const commitDescription = React.useCallback(() => {
    if (currentDescription !== (node.description || "")) {
      onDescriptionChange(currentDescription);
    }
    setIsDescriptionDirty(false);
    setDraftDescription(node.description || "");
  }, [currentDescription, node.description, onDescriptionChange]);

  const openMetadataDialog = React.useCallback(() => {
    setMetadataValues(buildTopLevelMetadataValues(node));
    setDialogPropertyName(node.title || "");
    setMetadataDialogOpen(true);
  }, [node]);

  const confirmDestructiveAction = React.useCallback(() => {
    if (confirmAction === "eraseAll") onEraseAll();
    if (confirmAction === "eraseDescriptions") onEraseDescriptions();
    setConfirmAction(null);
  }, [confirmAction, onEraseAll, onEraseDescriptions]);

  return {
    metadataDialogOpen,
    setMetadataDialogOpen,
    confirmAction,
    setConfirmAction,
    metadataValues,
    setMetadataValues,
    draftTitle,
    setDraftTitle,
    setIsTitleDirty,
    draftDescription,
    setDraftDescription,
    setIsDescriptionDirty,
    dialogPropertyName,
    setDialogPropertyName,
    currentTitle,
    currentDescription,
    commitTitle,
    commitDescription,
    openMetadataDialog,
    confirmDestructiveAction,
  };
}

