// Get icon for data type
export const getTypeIcon = (type: string) => {
  switch (type) {
    case "string":
      return <Type className="h-4 w-4" />;
    case "number":
    case "integer":
      return <Hash className="h-4 w-4" />;
    case "boolean":
      return <ToggleLeft className="h-4 w-4" />;
    case "enum":
      return <List className="h-4 w-4" />;
    case "object":
      return <Braces className="h-4 w-4" />;
    case "array":
      return <Brackets className="h-4 w-4" />;
    case "date":
      return <Calendar className="h-4 w-4" />;
    case "time":
      return <Clock className="h-4 w-4" />;
    case "datetime":
      return <CalendarClock className="h-4 w-4" />;
    case "$ref":
      return <Link className="h-4 w-4" />;
    default:
      return <Shapes className="h-4 w-4" />;
  }
};

// Get icon for template objects
export const getTemplateIcon = (templateName: string) => {
  switch (templateName) {
    case "Address":
      return <MapPin className="h-4 w-4" />;
    case "Price":
      return <DollarSign className="h-4 w-4" />;
    case "Person":
      return <User className="h-4 w-4" />;
    case "Company":
      return <Building2 className="h-4 w-4" />;
    case "Event":
      return <CalendarDays className="h-4 w-4" />;
    default:
      return <Link className="h-4 w-4" />;
  }
};

"use client";

import * as React from "react";

import {
  fromJsonSchema,
  toJsonSchema,
} from "@/components/schema-editor/document/convert";
import type { SchemaDocument } from "@/components/schema-editor/document/types";
import type {
  ExtendedJSONSchema7,
  SchemaBuilderState,
} from "@/components/schema-editor/schema-builder-types";
import { requireAllProperties } from "@/components/schema-editor/schema-required-policy";
import { validateProjectedSchema } from "@/components/schema-editor/validation";
import { useKeyedLayoutEffect } from "@/hooks/use-keyed-layout-effect";
import { joinEffectKey } from "@/lib/effect-key";

export interface UseSchemaBuilderStateOptions {
  value: ExtendedJSONSchema7;
  onValueChange: (schema: ExtendedJSONSchema7) => void;
  readOnly?: boolean;
  onPersist?: (schema: ExtendedJSONSchema7) => Promise<void>;
}

export function schemaSignature(value: unknown): string {
  return JSON.stringify(value);
}

export function projectSchemaDocument(
  doc: SchemaDocument,
): ExtendedJSONSchema7 {
  return requireAllProperties(toJsonSchema(doc)) as ExtendedJSONSchema7;
}

export function useSchemaBuilderState({
  value,
  onValueChange,
  readOnly = false,
  onPersist,
}: UseSchemaBuilderStateOptions): SchemaBuilderState {
  const [initialSignature] = React.useState(() => schemaSignature(value));
  const [doc, setDoc] = React.useState<SchemaDocument>(() =>
    fromJsonSchema(value),
  );

  const lastImportedSignatureRef = React.useRef(initialSignature);
  const lastEmittedSignatureRef = React.useRef<string | null>(null);

  const propSignature = React.useMemo(() => schemaSignature(value), [value]);

  useKeyedLayoutEffect(joinEffectKey([propSignature, value]), () => {
    if (propSignature === lastEmittedSignatureRef.current) {
      lastImportedSignatureRef.current = propSignature;
      return;
    }

    if (propSignature !== lastImportedSignatureRef.current) {
      lastImportedSignatureRef.current = propSignature;
      setDoc(fromJsonSchema(value));
    }
  });

  const schema = React.useMemo(() => projectSchemaDocument(doc), [doc]);
  const validation = React.useMemo(
    () => validateProjectedSchema(schema),
    [schema],
  );

  const docRef = React.useRef(doc);
  useKeyedLayoutEffect(joinEffectKey([doc]), () => {
    docRef.current = doc;
  });

  const schemaRef = React.useRef(schema);
  useKeyedLayoutEffect(joinEffectKey([schema]), () => {
    schemaRef.current = schema;
  });

  const emitSchema = React.useCallback(
    (nextDoc: SchemaDocument, persist: boolean | undefined) => {
      const nextSchema = projectSchemaDocument(nextDoc);
      const nextSignature = schemaSignature(nextSchema);
      lastEmittedSignatureRef.current = nextSignature;
      lastImportedSignatureRef.current = nextSignature;
      schemaRef.current = nextSchema;
      onValueChange(nextSchema);
      if ((persist ?? true) && onPersist) {
        void onPersist(nextSchema);
      }
    },
    [onPersist, onValueChange],
  );

  const dispatch = React.useCallback(
    (op: (doc: SchemaDocument) => SchemaDocument, persist?: boolean) => {
      if (readOnly) return;

      const previous = docRef.current;
      const next = op(previous);
      if (next === previous) return;

      docRef.current = next;
      setDoc(next);
      emitSchema(next, persist);
    },
    [emitSchema, readOnly],
  );

  const replaceSchema = React.useCallback(
    async (
      nextValue: React.SetStateAction<ExtendedJSONSchema7>,
      persist?: boolean,
    ) => {
      if (readOnly) return;

      const resolved = requireAllProperties(
        typeof nextValue === "function"
          ? nextValue(schemaRef.current)
          : nextValue,
      ) as ExtendedJSONSchema7;
      const nextSignature = schemaSignature(resolved);

      if (nextSignature === schemaSignature(schemaRef.current)) {
        if ((persist ?? true) && onPersist) {
          await onPersist(resolved);
        }
        return;
      }

      const nextDoc = fromJsonSchema(resolved);
      docRef.current = nextDoc;
      setDoc(nextDoc);
      lastEmittedSignatureRef.current = nextSignature;
      lastImportedSignatureRef.current = nextSignature;
      schemaRef.current = resolved;
      onValueChange(resolved);

      if ((persist ?? true) && onPersist) {
        await onPersist(resolved);
      }
    },
    [onPersist, onValueChange, readOnly],
  );

  return {
    doc,
    schema,
    validation,
    dispatch,
    replaceSchema,
  };
}

"use client";

import { useState } from "react";
import { AlertCircle, ChevronDown, ChevronRight } from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";

interface ValidationErrorDisplayProps {
  validationErrors?: string | null;
  className?: string;
  /** Whether to show the full error panel or just an inline indicator. */
  variant?: "full" | "inline" | "compact";
}

export function ValidationErrorDisplay({
  validationErrors,
  className,
  variant = "full",
}: ValidationErrorDisplayProps) {
  const [isExpanded, setIsExpanded] = useState(false);

  if (!validationErrors) {
    return null;
  }

  const errorItems = validationErrors.split("\n\n").filter(Boolean);

  const toggle = (
    <Button
      type="button"
      variant="ghost"
      onClick={() => setIsExpanded(!isExpanded)}
      className="text-destructive hover:bg-destructive/10 hover:text-destructive h-auto w-full justify-start gap-2 px-2 py-1.5"
      title={isExpanded ? "Collapse error details" : "Expand error details"}
    >
      {isExpanded ? (
        <ChevronDown className="size-4 shrink-0" />
      ) : (
        <ChevronRight className="size-4 shrink-0" />
      )}
      <AlertCircle className="size-4 shrink-0" />
      <span className="text-sm font-medium">
        {variant === "compact"
          ? `${errorItems.length} validation error${errorItems.length !== 1 ? "s" : ""}`
          : `Schema validation errors (${errorItems.length})`}
      </span>
    </Button>
  );

  const errorList = isExpanded ? (
    <div className="border-destructive/30 space-y-2 border-t px-3 py-2">
      {errorItems.map((error, index) => (
        <p
          key={index}
          className="text-destructive text-sm leading-relaxed break-words whitespace-pre-wrap"
        >
          {error}
        </p>
      ))}
    </div>
  ) : null;

  if (variant === "compact") {
    return (
      <div className={cn("border-destructive border-l-2", className)}>
        {toggle}
        {errorList}
      </div>
    );
  }

  return (
    <div
      className={cn(
        "border-destructive bg-destructive/10 rounded-md border",
        className,
      )}
    >
      {toggle}
      {errorList}
    </div>
  );
}

"use client";

import type { ErrorObject } from "ajv";
import type { JSONSchema7Definition } from "json-schema";

import {
  errorsText,
  getJsonSchemaValidationErrors,
  validateJsonSchema,
} from "@/components/schema-editor/schema-validation";
import type {
  ExtendedJSONSchema7,
  SchemaValidationIssue,
  SchemaValidationResult,
} from "@/components/schema-editor/schema-builder-types";
import { decodeJsonPointerSegment } from "@/components/schema-editor/document/json-pointer";

const PROPERTY_LIMIT = 500;

const SCHEMA_VALUE_KEYS = [
  "additionalItems",
  "additionalProperties",
  "contains",
  "else",
  "if",
  "not",
  "propertyNames",
  "then",
  "unevaluatedItems",
  "unevaluatedProperties",
] as const;

const SCHEMA_MAP_KEYS = [
  "$defs",
  "definitions",
  "dependentSchemas",
  "dependencies",
  "patternProperties",
] as const;

export function validateProjectedSchema(
  schema: ExtendedJSONSchema7,
): SchemaValidationResult {
  const propertyCount = countSchemaProperties(schema);
  const isPropertyLimitExceeded = propertyCount > PROPERTY_LIMIT;
  const ajvValid = validateJsonSchema(schema);
  const ajvErrors = processValidationErrors(getJsonSchemaValidationErrors());
  const errors = ajvErrors.map(errorToIssue);

  if (isPropertyLimitExceeded) {
    errors.unshift({
      code: "property_limit_exceeded",
      path: "",
      message: `Schema has too many properties: ${propertyCount}. Maximum accepted is ${PROPERTY_LIMIT}. Please reduce the number of properties.`,
    });
  }

  return {
    isValid: ajvValid && !isPropertyLimitExceeded,
    errors,
    propertyCount,
    isPropertyLimitExceeded,
  };
}

export function validationErrorsText(
  validation: SchemaValidationResult,
): string | undefined {
  if (validation.isValid) return undefined;
  return validation.errors.map((issue) => issue.message).join("\n\n");
}

export function countSchemaProperties(schema?: ExtendedJSONSchema7): number {
  if (!schema || typeof schema !== "object") return 0;

  const resolveLocalRef = (ref: string): ExtendedJSONSchema7 | undefined => {
    if (!ref.startsWith("#/")) return undefined;

    const segments = ref.substring(2).split("/").map(decodeJsonPointerSegment);
    let refSchema: unknown = schema;
    for (const segment of segments) {
      if (refSchema && typeof refSchema === "object") {
        const record = refSchema as Record<string, unknown>;
        if (!Object.prototype.hasOwnProperty.call(record, segment)) {
          return undefined;
        }
        refSchema = record[segment];
      } else {
        return undefined;
      }
    }

    return refSchema && typeof refSchema === "object"
      ? (refSchema as ExtendedJSONSchema7)
      : undefined;
  };

  const countedSchemas = new Set<ExtendedJSONSchema7>();

  const countProperties = (
    node: ExtendedJSONSchema7,
    path: string = "",
    activeSchemas: Set<ExtendedJSONSchema7> = new Set(),
  ): number => {
    if (!node || typeof node !== "object") return 0;
    if (countedSchemas.has(node)) return 0;
    countedSchemas.add(node);

    let count = 0;

    if (node.$ref && typeof node.$ref === "string") {
      const refSchema = resolveLocalRef(node.$ref);
      if (refSchema && !activeSchemas.has(refSchema)) {
        count += countProperties(
          refSchema,
          `${path}>${node.$ref}`,
          new Set([...activeSchemas, refSchema]),
        );
      }
    }

    if (node.properties && typeof node.properties === "object") {
      count += Object.keys(node.properties).length;
      Object.entries(node.properties).forEach(([propertyName, propSchema]) => {
        count += countProperties(
          propSchema as ExtendedJSONSchema7,
          `${path}/properties/${propertyName}`,
          activeSchemas,
        );
      });
    }

    if (node.items) {
      if (Array.isArray(node.items)) {
        node.items.forEach((item, index) => {
          count += countProperties(
            item as ExtendedJSONSchema7,
            `${path}/items/${index}`,
            activeSchemas,
          );
        });
      } else {
        count += countProperties(
          node.items as ExtendedJSONSchema7,
          `${path}/items`,
          activeSchemas,
        );
      }
    }

    const record = node as Record<string, unknown>;
    if (Array.isArray(record.prefixItems)) {
      record.prefixItems.forEach((item, index) => {
        count += countProperties(
          item as ExtendedJSONSchema7,
          `${path}/prefixItems/${index}`,
          activeSchemas,
        );
      });
    }

    for (const keyword of ["allOf", "anyOf", "oneOf"] as const) {
      const compositionArray = record[keyword];
      if (Array.isArray(compositionArray)) {
        compositionArray.forEach((subSchema, index) => {
          count += countProperties(
            subSchema as ExtendedJSONSchema7,
            `${path}/${keyword}/${index}`,
            activeSchemas,
          );
        });
      }
    }

    for (const keyword of SCHEMA_VALUE_KEYS) {
      const value = record[keyword];
      if (isSchemaObject(value)) {
        count += countProperties(
          value as ExtendedJSONSchema7,
          `${path}/${keyword}`,
          activeSchemas,
        );
      }
    }

    for (const keyword of SCHEMA_MAP_KEYS) {
      const value = record[keyword];
      if (!isSchemaObject(value)) continue;

      for (const [name, child] of Object.entries(value)) {
        count += countProperties(
          child as ExtendedJSONSchema7,
          `${path}/${keyword}/${name}`,
          activeSchemas,
        );
      }
    }

    return count;
  };

  return countProperties(schema);
}

function isSchemaObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

export function processValidationErrors(
  errors: ErrorObject[] | null | undefined,
): ErrorObject[] {
  if (!errors || errors.length === 0) return [];

  const processedErrors: ErrorObject[] = [];
  const processedPropertyNames = new Set<string>();

  for (const error of errors) {
    if (
      error.keyword === "pattern" &&
      error.schemaPath?.includes("/propertyNames/pattern") &&
      error.data &&
      typeof error.data === "string"
    ) {
      const propertyName = error.data;
      if (!processedPropertyNames.has(propertyName)) {
        processedErrors.push({
          keyword: "propertyNames",
          instancePath: error.instancePath,
          schemaPath: error.schemaPath,
          params: { propertyName },
          message: `Property name "${propertyName}" must not be purely numeric`,
          data: error.data,
          schema: error.schema,
        });
        processedPropertyNames.add(propertyName);
      }
    } else if (
      error.keyword === "propertyNames" &&
      error.params?.propertyName
    ) {
      const propertyName = error.params.propertyName;
      if (!processedPropertyNames.has(propertyName)) {
        processedErrors.push({
          keyword: "propertyNames",
          instancePath: error.instancePath,
          schemaPath: error.schemaPath,
          params: { propertyName },
          message: `Property name "${propertyName}" must not be purely numeric`,
          data: error.data,
          schema: error.schema,
        });
        processedPropertyNames.add(propertyName);
      }
    } else if (
      error.keyword === "const" &&
      error.schemaPath?.includes("/additionalProperties/const")
    ) {
      processedErrors.push({
        keyword: "additionalProperties",
        instancePath: error.instancePath,
        schemaPath: error.schemaPath,
        params: error.params,
        message:
          "`additionalProperties` are forbidden, if present they MUST be false.",
        data: error.data,
        schema: error.schema,
      });
    } else if (
      error.keyword !== "propertyNames" &&
      !(
        error.keyword === "pattern" &&
        error.schemaPath?.includes("/propertyNames/pattern")
      ) &&
      !(
        error.keyword === "const" &&
        error.schemaPath?.includes("/additionalProperties/const")
      )
    ) {
      processedErrors.push(error);
    }
  }

  return processedErrors;
}

function errorToIssue(error: ErrorObject): SchemaValidationIssue {
  if (error.keyword === "propertyNames") {
    return {
      code: "numeric_property_name",
      path: error.instancePath,
      message:
        error.message ??
        `Property name "${String(error.params?.propertyName ?? "")}" must not be purely numeric`,
      source: error,
    };
  }

  if (error.keyword === "additionalProperties") {
    return {
      code: "additional_properties_not_false",
      path: error.instancePath,
      message:
        error.message ??
        "`additionalProperties` are forbidden, if present they MUST be false.",
      source: error,
    };
  }

  return {
    code: "invalid_schema",
    path: error.instancePath,
    message:
      error.message ??
      errorsText([error], {
        separator: "\n\n",
      }),
    source: error,
  };
}

export function isJsonSchemaDefinition(
  value: unknown,
): value is JSONSchema7Definition {
  return (
    typeof value === "boolean" || (typeof value === "object" && value !== null)
  );
}

"use client";

import * as React from "react";
import { ChevronDownIcon } from "lucide-react";
import { Accordion as AccordionPrimitive } from "radix-ui";

import { cn } from "@/lib/utils";

function Accordion({
  ...props
}: React.ComponentProps<typeof AccordionPrimitive.Root>) {
  return <AccordionPrimitive.Root data-slot="accordion" {...props} />;
}

function AccordionItem({
  className,
  ...props
}: React.ComponentProps<typeof AccordionPrimitive.Item>) {
  return (
    <AccordionPrimitive.Item
      data-slot="accordion-item"
      className={cn("border-b last:border-b-0", className)}
      {...props}
    />
  );
}

function AccordionTrigger({
  className,
  children,
  ...props
}: React.ComponentProps<typeof AccordionPrimitive.Trigger>) {
  return (
    <AccordionPrimitive.Header className="flex">
      <AccordionPrimitive.Trigger
        data-slot="accordion-trigger"
        className={cn(
          "focus-visible:border-ring focus-visible:ring-ring/50 flex flex-1 items-start justify-between gap-4 rounded-md py-4 text-left text-sm font-medium transition-all outline-none hover:underline focus-visible:ring-[3px] disabled:pointer-events-none disabled:opacity-50 [&[data-state=open]>svg]:rotate-180",
          className,
        )}
        {...props}
      >
        {children}
        <ChevronDownIcon className="text-muted-foreground pointer-events-none size-4 shrink-0 translate-y-0.5 transition-transform duration-200" />
      </AccordionPrimitive.Trigger>
    </AccordionPrimitive.Header>
  );
}

function AccordionContent({
  className,
  children,
  ...props
}: React.ComponentProps<typeof AccordionPrimitive.Content>) {
  return (
    <AccordionPrimitive.Content
      data-slot="accordion-content"
      className="data-[state=closed]:animate-accordion-up data-[state=open]:animate-accordion-down overflow-hidden text-sm"
      {...props}
    >
      <div className={cn("pt-0 pb-4", className)}>{children}</div>
    </AccordionPrimitive.Content>
  );
}

export { Accordion, AccordionItem, AccordionTrigger, AccordionContent };
